import React, { createContext, useContext, useState, useEffect } from 'react';

const ThemeContext = createContext();

export const ThemeProvider = ({ children }) => {
  // --- 1. THEME LOGIC (Preserved exactly as requested) ---
  const [theme, setTheme] = useState(() => {
    if (typeof window !== 'undefined') {
      const savedTheme = localStorage.getItem('theme');
      if (savedTheme) return savedTheme;
      if (window.matchMedia && window.matchMedia('(prefers-color-scheme: dark)').matches) {
        return 'dark';
      }
      return 'light';
    }
    return 'dark';
  });


  // Set <body data-theme> attribute for CSS variables
  useEffect(() => {
    document.body.setAttribute('data-theme', theme);
  }, [theme]);

  useEffect(() => {
    localStorage.setItem('theme', theme);
  }, [theme]);

  const toggleTheme = () => {
    setTheme(prev => (prev === 'dark' ? 'light' : 'dark'));
  };

  // --- 2. GITHUB JSON LOGIC (The "Extra Part") ---
  const [config, setConfig] = useState(null);
  const [loading, setLoading] = useState(true);

  const RAW_JSON_URL = "https://raw.githubusercontent.com/yogeshjamnor/my-website/refs/heads/main/coding_hub_backend.json";

  useEffect(() => {
    const fetchConfig = async () => {
      try {
        const response = await fetch(`${RAW_JSON_URL}?t=${Date.now()}`);
        const text = await response.text();
        const sanitized = text.replace(/,\s*([}\]])/g, '$1');
        const data = JSON.parse(sanitized);
        setConfig(data);
      } catch (error) {
        console.error("Error loading dynamic config:", error);
      } finally {
        setLoading(false);
      }
    };
    fetchConfig();
  }, []);

  // --- 3. COMBINED VALUE ---
  return (
    <ThemeContext.Provider value={{ theme, toggleTheme, config, loading }}>
      {children}
    </ThemeContext.Provider>
  );
};

export const useTheme = () => useContext(ThemeContext);