import React ,{useState}from 'react';
import 'bootstrap/dist/css/bootstrap.min.css';
import 'bootstrap-icons/font/bootstrap-icons.css';
import { useTheme } from '../component/ThemeContext';

export default function Wikipedia() {
  const { theme } = useTheme();
  const isDark = theme === 'dark';

  const [query, setQuery] = useState('');
  const [results, setResults] = useState([]);

  const fetchData = async (q) => {
    try {
      const response = await fetch(`https://en.wikipedia.org/w/api.php?action=query&list=search&srsearch=${q}&format=json`);
      const data = await response.json();
      const results = data.query.search.map((result, index) => (
        <div key={index} style={{ background: isDark ? 'rgba(30, 41, 59, 0.8)' : '#ffffff', border: `1px solid ${isDark ? 'rgba(255,255,255,0.08)' : 'rgba(0,0,0,0.08)'}`, borderRadius: 8, padding: 15,  marginBottom: 10 }}>                
          <h2 style={{ color: isDark ? '#e2e8f0' : '#1f2937' }}>{result.title}</h2>
          <p style={{ color: isDark ? '#cbd5e1' : '#6b7280' }} dangerouslySetInnerHTML={{ __html: result.snippet }}></p>
          <a href={`https://en.wikipedia.org/wiki/${encodeURIComponent(result.title)}`} target="_blank" rel="noopener noreferrer" style={{ color: '#3b82f6' }}>
            Read more
          </a>
        </div>
      ));
      setResults(results);
    } catch (error) {
      console.error('Error fetching data:', error);
    }
  };

  const handleSearch = async (e) => {
    e.preventDefault();
    fetchData(query);
  };

  return (
    <form onSubmit={handleSearch} style={{ maxWidth: 600, margin: '0 auto' }}>
      <input
        type="text"
        value={query}
        onChange={(e) => setQuery(e.target.value)}
        placeholder="Type a search term..."
        style={{
          width: '100%',
          padding: '10px 15px',
          borderRadius: 8,
          border: `1px solid ${isDark ? 'rgba(255,255,255,0.08)' : 'rgba(0,0,0,0.08)'}`,
          marginBottom: 20,
          background: isDark ? 'rgba(30, 41, 59, 0.8)' : '#ffffff',
          color: isDark ? '#e2e8f0' : '#1f2937',
        }}
      />
      {results.length > 0 ? (
        <div>
          {results}
        </div>
      ) : (
        <p style={{ color: isDark ? '#cbd5e1' : '#6b7280' }}>No results found.</p>
      )}
    </form>
  );
};  