import React, { useEffect, useState } from 'react';
import { Navbar as RBNavbar, Container, Row, Col, Nav, Image } from 'react-bootstrap';
import AOS from 'aos';
import 'aos/dist/aos.css';
import 'bootstrap-icons/font/bootstrap-icons.css';
import { useTheme } from './ThemeContext';

export default function Topbar({ sidebarOpen, toggleSidebar }) {
  const { theme } = useTheme();
  const isDark = theme === 'dark';

  const [hovered, setHovered] = useState(false);
  const [hoverLink, setHoverLink] = useState(null);
  const [activeLink, setActiveLink] = useState('Home');

  useEffect(() => {
    AOS.init({ duration: 600, easing: 'ease-in-out', once: true });
  }, []);

  const navItems = [
    { name: 'Home', icon: 'house' },
    { name: 'About', icon: 'info-circle' },
    { name: 'Contact', icon: 'telephone-outbound' },
  ];

  // theme palette (used consistently across component)
  const accent = '#ffc107';
  const bg = isDark ? 'rgba(8,10,12,0.70)' : 'rgba(255,255,255,0.90)';
  const border = isDark ? '1px solid rgba(255,255,255,0.06)' : '1px solid rgba(0,0,0,0.06)';
  const softShadow = isDark ? '0 6px 20px rgba(0,0,0,0.55)' : '0 6px 18px rgba(0,0,0,0.08)';
  const textBase = isDark ? '#F5FAFF' : '#081428';
  const muted = isDark ? 'rgba(245,250,255,0.65)' : 'rgba(8,20,40,0.6)';

  return (
    <RBNavbar
      fixed="top"
      data-aos="fade-down"
      style={{
        height: '64px',
        background: bg,
        backdropFilter: 'saturate(120%) blur(8px)',
        borderBottom: border,
        boxShadow: softShadow,
        zIndex: 1100,
        transition: 'background 0.25s ease, color 0.25s ease',
      }}
      role="navigation"
      aria-label="Top navigation"
    >
      <Container fluid className="px-3">
        <Row className="align-items-center w-100 flex-nowrap">

          {/* SIDEBAR TOGGLE */}
          <Col xs="auto" className="d-flex align-items-center">
            <button
              onClick={toggleSidebar}
              onMouseEnter={() => setHovered(true)}
              onMouseLeave={() => setHovered(false)}
              className="border-0 bg-transparent p-1"
              aria-label="Toggle sidebar"
            >
              <i
                className={`bi ${sidebarOpen ? 'bi-box-arrow-left' : 'bi-box-arrow-right'} fs-4`}
                style={{
                  color: hovered ? accent : textBase,
                  transition: 'color 0.18s ease',
                }}
              />
            </button>
          </Col>

          {/* LOGO */}
          <Col xs="auto" className="d-flex align-items-center gap-2">
            <Image
              src="/img/code.png"
              width={36}
              height={36}
              roundedCircle
              loading="lazy"
              alt="Coding Hub logo"
              style={{
                border: `2px solid ${accent}`,
                objectFit: 'cover',
                boxShadow: isDark ? '0 4px 10px rgba(0,0,0,0.55)' : '0 4px 12px rgba(0,0,0,0.08)',
              }}
            />
            <span
              className="d-none d-sm-inline"
              style={{
                fontWeight: 700,
                letterSpacing: '0.4px',
                color: textBase,
                fontSize: 16,
              }}
            >
              Coding Hub
            </span>
          </Col>

          {/* NAV LINKS */}
          <Col className="d-flex justify-content-end">
            <Nav className="align-items-center gap-2 gap-md-5 flex-nowrap">
              {navItems.map(({ name, icon }) => {
                const isActive = activeLink === name;
                const isHover = hoverLink === name;

                const activeColor = isActive || isHover ? accent : textBase;

                return (
                  <Nav.Link
                    key={name}
                    href={name === 'Home' ? '/' : `/${name.toLowerCase()}`}
                    onClick={() => setActiveLink(name)}
                    onMouseEnter={() => setHoverLink(name)}
                    onMouseLeave={() => setHoverLink(null)}
                    style={{
                      position: 'relative',
                      fontWeight: 600,
                      color: activeColor,
                      paddingBottom: '6px',
                      transition: 'color 0.18s ease',
                    }}
                    aria-current={isActive ? 'page' : undefined}
                    aria-label={`${name} page`}
                  >
                    {/* TEXT (DESKTOP) */}
                    <span className="d-none d-md-inline text-uppercase" style={{ fontSize: '14px', letterSpacing: '0.6px' }}>
                      {name}
                    </span>

                    {/* ICON (MOBILE) */}
                    <span className="d-inline d-md-none fs-5" aria-hidden>
                      <i className={`bi bi-${icon}`} />
                    </span>

                    {/* ACTIVE / HOVER LINE (DESKTOP ONLY) */}
                    <span
                      className="d-none d-md-block"
                      style={{
                        position: 'absolute',
                        bottom: 0,
                        left: 0,
                        width: isActive || isHover ? '100%' : '0%',
                        height: '2px',
                        backgroundColor: accent,
                        transition: 'width 0.28s ease',
                      }}
                    />
                  </Nav.Link>
                );
              })}
            </Nav>
          </Col>

        </Row>
      </Container>
    </RBNavbar>
  );
}
