import React, { useState, useRef, useEffect } from "react";
import { PDFDocument } from "pdf-lib";
import { useTheme } from "../component/ThemeContext";

export default function PdfSplit() {
  const { theme } = useTheme();
  const isDark = theme === "dark";

  const [file, setFile] = useState(null);
  const [previewUrl, setPreviewUrl] = useState(null);
  const [metadata, setMetadata] = useState(null);
  const [pageRange, setPageRange] = useState("");
  const [loading, setLoading] = useState(false);
  const [downloads, setDownloads] = useState([]);
  const cardRef = useRef(null);
  const [isFullscreen, setIsFullscreen] = useState(false);

  const handleUpload = async (e) => {
    const selected = e.target.files[0];
    if (!selected || selected.type !== "application/pdf") {
      alert("Please upload a valid PDF.");
      return;
    }

    if (previewUrl) URL.revokeObjectURL(previewUrl);

    setFile(selected);
    setPreviewUrl(URL.createObjectURL(selected));
    setDownloads([]);
    setLoading(true);

    try {
      const bytes = await selected.arrayBuffer();
      const pdfDoc = await PDFDocument.load(bytes);

      setMetadata({
        name: selected.name,
        size: (selected.size / 1024).toFixed(2) + " KB",
        pages: pdfDoc.getPageCount()
      });
    } catch (err) {
      console.error(err);
      alert("Failed to read PDF.");
    }

    setLoading(false);
  };

  const splitAllPages = async () => {
    if (!file) return alert("Upload a PDF first.");

    setLoading(true);
    const bytes = await file.arrayBuffer();
    const pdfDoc = await PDFDocument.load(bytes);
    const totalPages = pdfDoc.getPageCount();

    const newDownloads = [];

    for (let i = 0; i < totalPages; i++) {
      const newPdf = await PDFDocument.create();
      const [copiedPage] = await newPdf.copyPages(pdfDoc, [i]);
      newPdf.addPage(copiedPage);

      const pdfBytes = await newPdf.save();
      const blob = new Blob([pdfBytes], { type: "application/pdf" });
      const url = URL.createObjectURL(blob);

      newDownloads.push({
        name: `Page_${i + 1}.pdf`,
        url,
        blob
      });
    }

    setDownloads(newDownloads);
    setLoading(false);
  };

  const splitCustomRange = async () => {
    if (!file) return alert("Upload a PDF first.");
    if (!pageRange) return alert("Enter page range (e.g., 1-3,5)");

    setLoading(true);

    try {
      const bytes = await file.arrayBuffer();
      const pdfDoc = await PDFDocument.load(bytes);
      const totalPages = pdfDoc.getPageCount();

      const pagesToExtract = [];

      pageRange.split(",").forEach(part => {
        if (part.includes("-")) {
          const [start, end] = part.split("-").map(Number);
          for (let i = start; i <= end; i++) {
            pagesToExtract.push(i - 1);
          }
        } else {
          pagesToExtract.push(Number(part) - 1);
        }
      });

      const validPages = pagesToExtract.filter(p => p >= 0 && p < totalPages);

      const newPdf = await PDFDocument.create();
      const copiedPages = await newPdf.copyPages(pdfDoc, validPages);
      copiedPages.forEach(page => newPdf.addPage(page));

      const pdfBytes = await newPdf.save();
      const blob = new Blob([pdfBytes], { type: "application/pdf" });
      const url = URL.createObjectURL(blob);

      setDownloads([
        {
          name: `Split_${file.name}`,
          url,
          blob
        }
      ]);
    } catch (err) {
      console.error(err);
      alert("Invalid page range format.");
    }

    setLoading(false);
  };

  const toggleFullscreen = async () => {
    if (!cardRef.current) return;
    if (!document.fullscreenElement) {
      await cardRef.current.requestFullscreen();
    } else {
      await document.exitFullscreen();
    }
  };

  useEffect(() => {
    const onChange = () =>
      setIsFullscreen(Boolean(document.fullscreenElement));
    document.addEventListener("fullscreenchange", onChange);
    return () =>
      document.removeEventListener("fullscreenchange", onChange);
  }, []);

  // Runtime load JSZip from CDN when needed
  const ensureJsZip = () =>
    new Promise((resolve, reject) => {
      if (window.JSZip) return resolve(window.JSZip);
      const s = document.createElement("script");
      s.src = "https://cdn.jsdelivr.net/npm/jszip@3.10.1/dist/jszip.min.js";
      s.onload = () => resolve(window.JSZip);
      s.onerror = (e) => reject(e);
      document.head.appendChild(s);
    });

  const downloadAllZip = async () => {
    if (!downloads || downloads.length === 0) return;
    setLoading(true);
    try {
      const JSZip = await ensureJsZip();
      const zip = new JSZip();
      downloads.forEach((d) => {
        if (d.blob) zip.file(d.name, d.blob);
      });

      const content = await zip.generateAsync({ type: "blob" });
      const zurl = URL.createObjectURL(content);
      const a = document.createElement("a");
      a.href = zurl;
      a.download = `${file ? file.name.replace(/\.pdf$/i, "") : "files"}_pages.zip`;
      a.click();
      setTimeout(() => URL.revokeObjectURL(zurl), 10000);
    } catch (err) {
      console.error("ZIP creation failed", err);
      // fallback: trigger individual downloads
      downloads.forEach(d => {
        const a = document.createElement('a');
        a.href = d.url;
        a.download = d.name;
        a.click();
      });
    } finally {
      setLoading(false);
    }
  };

  return (
    <div
      className={`container-fluid ${isDark ? "bg-dark text-light" : "bg-light text-dark"}`}
      style={{ minHeight: "100vh", padding: "2rem" }}
    >
      <div
        ref={cardRef}
        className={`card shadow-lg border-0 mx-auto ${isDark ? "bg-dark text-light" : "bg-white"}`}
        style={{
          maxWidth: isFullscreen ? "100%" : "1200px",
          height: isFullscreen ? "100vh" : undefined
        }}
      >
        {/* Header */}
        <div className={`card-header d-flex justify-content-between align-items-center ${isDark ? "bg-dark border-secondary" : "bg-light"}`}>
          <h5 className="m-0 fw-bold">
            <i className="bi bi-scissors me-2"></i>
            PDF Split Tool
          </h5>

          <div className="d-flex gap-2">
            <input
              type="file"
              accept="application/pdf"
              onChange={handleUpload}
              className="form-control form-control-sm"
              style={{ width: "220px" }}
            />
            <button
              className="btn btn-sm btn-outline-success"
              onClick={toggleFullscreen}
            >
              <i className={isFullscreen ? "bi bi-arrows-collapse" : "bi bi-arrows-fullscreen"}></i>
            </button>
          </div>
        </div>

        <div className="row g-0" style={{ height: "750px" }}>
          
          {/* LEFT SIDE */}
          <div className={`col-md-4 border-end p-4 overflow-auto ${isDark ? "border-secondary" : ""}`}>
            {metadata && (
              <>
                <h6 className="fw-bold">File Info</h6>
                <p><strong>Name:</strong> {metadata.name}</p>
                <p><strong>Size:</strong> {metadata.size}</p>
                <p><strong>Pages:</strong> {metadata.pages}</p>

                <hr />

                <h6 className="fw-bold mt-3">Split Options</h6>

                <button
                  className="btn btn-primary w-100 mb-2"
                  onClick={splitAllPages}
                  disabled={loading}
                >
                  Split All Pages
                </button>

                <input
                  type="text"
                  className="form-control mb-2"
                  placeholder="Custom range (e.g. 1-3,5)"
                  value={pageRange}
                  onChange={(e) => setPageRange(e.target.value)}
                />

                <button
                  className="btn btn-warning w-100"
                  onClick={splitCustomRange}
                  disabled={loading}
                >
                  Split Custom Range
                </button>

                {downloads.length > 0 && (
                  <>
                    <hr />
                    <h6 className="fw-bold">Downloads</h6>
                    <div className="d-flex gap-2 mb-2">
                      <button className="btn btn-secondary btn-sm" onClick={downloadAllZip} disabled={loading}>
                        <i className="bi bi-download me-1"></i> Download All (ZIP)
                      </button>
                      <button className="btn btn-outline-secondary btn-sm" onClick={() => {
                        // revoke and clear
                        downloads.forEach(d => d.url && URL.revokeObjectURL(d.url));
                        setDownloads([]);
                      }}>
                        Clear Downloads
                      </button>
                    </div>
                    {downloads.map((d, i) => (
                      <a
                        key={i}
                        href={d.url}
                        download={d.name}
                        className="btn btn-success btn-sm w-100 mb-2"
                      >
                        <i className="bi bi-download me-1"></i>
                        {d.name}
                      </a>
                    ))}
                  </>
                )}
              </>
            )}

            {!metadata && <p className="text-muted">Upload a PDF to split.</p>}
          </div>

          {/* RIGHT SIDE - PREVIEW */}
          <div className="col-md-8 bg-secondary bg-opacity-10">
            {previewUrl ? (
              <iframe
                src={previewUrl}
                title="PDF Preview"
                className="w-100 h-100 border-0"
              />
            ) : (
              <div className="d-flex justify-content-center align-items-center h-100 text-muted">
                PDF preview will appear here
              </div>
            )}
          </div>

        </div>
      </div>
    </div>
  );
}
