import React, { useEffect, useState } from 'react';
import { NavLink } from 'react-router-dom';
import AOS from 'aos';
import 'aos/dist/aos.css';
import 'bootstrap-icons/font/bootstrap-icons.css';
import { useTheme } from './ThemeContext';

export default function Sidebar({ show }) {
  const { theme, toggleTheme } = useTheme();
  const isDark = theme === 'dark';

  const [openDropdown, setOpenDropdown] = useState(null);
  const [hoveredItem, setHoveredItem] = useState(null);

  useEffect(() => {
    AOS.init({ duration: 600, easing: 'ease-in-out', once: true });
  }, []);

  /* ================= SIDEBAR ITEMS ================= */

 const SIDEBAR_ITEMS = [
  {
    type: 'dropdown',
    label: 'Convert',
    icon: 'shuffle',
    children: [
      { label: 'Image', to: '/img' },
      { label: 'PDF', to: '/pdf' },
       ],
  },

  {
    type: 'dropdown',
    label: 'Developer',
    icon: 'code-slash',
    children: [
      { label: 'Code', to: '/code' },
      { label: 'Commands', to: '/cmds' },
      { label: 'Execute Code', to: '/terminal' },
      { label: 'Theory',to: '/notes',  },
      { label: 'AI',to: '/ai',  },
    ],
  },

  {
    type: 'link',
    label: 'Learning',
    icon: 'book',
   to: '/learn',
  },
 {
    type: 'link',
    label: 'Social',
    icon: 'gitlab',
   to: '/social',
  },
  {
    type: 'link',
    label: 'Game',
    icon: 'controller',
   to: '/game',
  },



];


  const sidebarStyle = {
    position: 'fixed',
    top: '80px',
    left: show ? '20px' : '-260px',
    width: '230px',
    height: 'auto',
    borderRadius: '22px',
    background: isDark ? 'rgba(78, 74, 74, 0.48)' : 'rgba(255,255,255,0.95)',
    backdropFilter: 'blur(14px)',
    paddingTop: '20px',
    zIndex: 1050,
    transition: 'left 0.4s ease',
    boxShadow: isDark
      ? '0 24px 60px rgba(0,0,0,0.65)'
      : '0 18px 45px rgba(0,0,0,0.18)',
  };

  const separatorStyle = {
    height: '1px',
    margin: '8px 0',
    background: isDark
      ? 'rgba(255,255,255,0.1)'
      : 'rgba(0,0,0,0.1)',
    border: 'none',
  };

  const baseLinkStyle = {
    padding: '10px 14px',
    borderRadius: '10px',
    textDecoration: 'none',
    display: 'flex',
    alignItems: 'center',
    gap: '8px',
    fontWeight: 500,
    transition: 'color 0.2s ease, background 0.2s ease',
  };

  // Icon color mapping for realistic styling
const getIconColor = (iconName, isDark) => {
  const iconColors = {
    'shuffle': '#00d4ff', // Cyan for Convert
    'code-slash': '#10b981', // Green for Developer
    'book': '#f59e0b', // Amber for Learning
    'graph-up': '#8b5cf6', // Purple for Analytics
    'android2': '#ec4899', // Pink for AI
    'person-gear': '#06b6d4', // Cyan for Account
  };
  return iconColors[iconName] || (isDark ? '#fff' : '#000');
};


  /* ================= JSX ================= */

  return (
    <div style={sidebarStyle} data-aos="fade-right">
      <div
        className="d-flex flex-column p-2"
        style={{
          height: '100%',
          overflowY: 'auto',
          scrollbarWidth: 'thin',
        }}
      >
        {/* HEADER */}
        <h5
          className="text-center mb-4 fw-semibold"
          style={{
            color: isDark ? '#fff' : '#000',
            letterSpacing: '0.5px',
            fontSize: '0.95rem',
          }}
        >
          <i className="bi bi-clipboard-check me-2"></i>
          My Task
        </h5>

        <ul className="nav flex-column gap-0 flex-grow-1" style={{ listStyle: 'none', padding: 0 }}>
          {SIDEBAR_ITEMS.map((item, idx) => (
            <li className="nav-item" key={idx}>
              {item.type === 'link' && (
                <>
                  <NavLink
                    to={item.to}
                    className="nav-link"
                    onMouseEnter={() => setHoveredItem(item.label)}
                    onMouseLeave={() => setHoveredItem(null)}
                    style={({ isActive }) => ({
                      ...baseLinkStyle,
                      color: isActive
                        ? '#ffc107'
                        : hoveredItem === item.label
                          ? '#ffc107'
                          : isDark
                            ? '#fff'
                            : '#000',
                      background: isActive
                        ? isDark
                          ? 'rgba(255,193,7,0.15)'
                          : 'rgba(255,193,7,0.2)'
                        : 'transparent',
                    })}
                  >
                    <i className={`bi bi-${item.icon}`} style={{ color: getIconColor(item.icon, isDark) }} />
                    {item.label}
                  </NavLink>
                  <div style={separatorStyle} />
                </>
              )}

              {/* ===== DROPDOWN ===== */}
              {item.type === 'dropdown' && (
                <>
                  <div
                    className="nav-link"
                    onMouseEnter={() => setHoveredItem(item.label)}
                    onMouseLeave={() => setHoveredItem(null)}
                    onClick={() =>
                      setOpenDropdown(openDropdown === idx ? null : idx)
                    }
                    style={{
                      ...baseLinkStyle,
                      cursor: 'pointer',
                      color:
                        hoveredItem === item.label
                          ? '#ffc107'
                          : isDark
                            ? '#fff'
                            : '#000',
                    }}
                  >
                    <i className={`bi bi-${item.icon}`} style={{ color: getIconColor(item.icon, isDark) }} />
                    <span className="flex-grow-1">{item.label}</span>
                    <i
                      className={`bi ${
                        openDropdown === idx ? 'bi-chevron-up' : 'bi-chevron-down'
                      }`}
                      style={{ fontSize: '0.85rem', color: isDark ? '#fff' : '#000' }}
                    />
                  </div>

                  {openDropdown === idx && (
                    <div className="ms-3 mt-2 mb-2">
                      {item.children.map((child, childIdx) => (
                        <div key={child.to}>
                          <NavLink
                            to={child.to}
                            className="nav-link small"
                            onMouseEnter={() => setHoveredItem(child.label)}
                            onMouseLeave={() => setHoveredItem(null)}
                            style={({ isActive }) => ({
                              ...baseLinkStyle,
                              padding: '8px 12px',
                              fontSize: '0.85rem',
                              color: isActive
                                ? '#ffc107'
                                : hoveredItem === child.label
                                  ? '#ffc107'
                                  : isDark
                                    ? '#ddd'
                                    : '#333',
                              borderLeft: isActive
                                ? '2px solid #ffc107'
                                : '2px solid transparent',
                            })}
                          >
                            <i
                              className="bi bi-dot"
                              style={{ fontSize: '0.6rem', marginRight: '4px', color: getIconColor(item.icon, isDark) }}
                            />
                            {child.label}
                          </NavLink>
                          {childIdx < item.children.length - 1 && (
                            <div
                              style={{
                                height: '1px',
                                margin: '4px 0 4px 12px',
                                background: isDark
                                  ? 'rgba(255,255,255,0.08)'
                                  : 'rgba(0,0,0,0.08)',
                              }}
                            />
                          )}
                        </div>
                      ))}
                    </div>
                  )}
                  <div style={separatorStyle} />
                </>
              )}
            </li>
          ))}
        </ul>

        {/* THEME TOGGLE SECTION */}
        <hr style={{ 
          color: isDark ? 'rgba(255,255,255,0.1)' : 'rgba(0,0,0,0.1)',
          border: 'none',
          height: '1px',
          margin: '8px 0',
        }} />

        <div 
          className="d-flex align-items-center justify-content-center px-2 py-3 m-2"
          style={{
            border: isDark ? '1px solid rgba(255,255,255,0.2)' : '1px solid rgba(0,0,0,0.1)',
            borderRadius: '10px',
            background: isDark ? 'rgba(255,255,255,0.02)' : 'rgba(0,0,0,0.02)',
          }}
        >
          <span 
            className="small fw-medium flex-grow-1 text-center"
            style={{ color: isDark ? '#fff' : '#000' }}
          >
            {isDark ? '🌙 Dark' : '☀️ Light'}
          </span>

          <label
            style={{
              position: 'relative',
              display: 'inline-block',
              width: '48px',
              height: '26px',
              cursor: 'pointer',
              marginLeft: '8px',
            }}
          >
            <input
              type="checkbox"
              checked={isDark}
              onChange={toggleTheme}
              style={{ opacity: 0, width: 0, height: 0 }}
            />

            {/* Track */}
            <span
              style={{
                position: 'absolute',
                inset: 0,
                backgroundColor: isDark ? '#ffc107' : '#ced4da',
                borderRadius: '50px',
                transition: 'background 0.3s ease',
              }}
            />

            {/* Thumb */}
            <span
              style={{
                position: 'absolute',
                top: '3px',
                left: isDark ? '26px' : '4px',
                width: '20px',
                height: '20px',
                backgroundColor: '#000',
                borderRadius: '50%',
                transition: 'left 0.3s ease',
                boxShadow: '0 2px 6px rgba(0,0,0,0.35)',
              }}
            />
          </label>
        </div>

        <hr style={{ 
          color: isDark ? 'rgba(255,255,255,0.1)' : 'rgba(0,0,0,0.1)',
          border: 'none',
          height: '1px',
          margin: '8px 0',
        }} />
      </div>
    </div>
  );
}
