import React from 'react';
import { NavLink } from 'react-router-dom';
import { useTheme } from './ThemeContext';

import 'bootstrap/dist/css/bootstrap.min.css';

function Error404() {
  const { theme } = useTheme();
  const isDark = theme === 'dark';

  return (
    <div
      className="container-fluid d-flex flex-column justify-content-center align-items-center text-center"
      style={{
        minHeight: '100vh',
        backgroundColor: isDark ? '#000' : '#fff',
        color: isDark ? '#fff' : '#000',
      }}
    >
      <div className="p-3">
        {/* MAIN ERROR TEXT */}
        <h1
          style={{
            color: '#ff0000',   // 🔴 always red
            fontWeight: 700,
          }}
        >
          Page Not Found
        </h1>

        {/* SUB TEXT */}
        <p
          style={{
            color: isDark ? '#ffffffcc' : '#000000b3',
            fontSize: '15px',
            marginTop: '10px',
          }}
        >
          The page you are searching for is not available.
          <br />
          Please go back to the default page.
        </p>
      </div>

      {/* HOME BUTTON */}
      <NavLink
        to="/"
        className="btn px-4 py-2 mt-3"
        style={{
          backgroundColor: '#ffc107',
          color: '#000',
          fontWeight: 600,
          borderRadius: '8px',
          textDecoration: 'none',
        }}
      >
        Go to Home
      </NavLink>
    </div>
  );
}

export default Error404;
