import React, { useState, useRef, useEffect } from "react";
import { useTheme } from "../component/ThemeContext";

export default function PdfToText() {
  const { theme } = useTheme();
  const isDark = theme === "dark";

  const [file, setFile] = useState(null);
  const [textOutput, setTextOutput] = useState("");
  const [loading, setLoading] = useState(false);
  const [progress, setProgress] = useState({ done: 0, total: 0 });
  const [skippedPages, setSkippedPages] = useState([]);
  const fileInputRef = useRef(null);
  const [ocrPages, setOcrPages] = useState([]);
  const [previewUrl, setPreviewUrl] = useState(null);
  const [showPreview, setShowPreview] = useState(false);
  const [startTime, setStartTime] = useState(null);
  const [elapsed, setElapsed] = useState(0);
  const [previewFullscreen, setPreviewFullscreen] = useState(false);

  const cardRef = useRef(null);
  const [isFullscreen, setIsFullscreen] = useState(false);

  const handleUpload = async (e) => {
    const selected = e.target.files[0];
    if (!selected || selected.type !== "application/pdf") {
      alert("Please upload a valid PDF.");
      return;
    }

    // manage preview URL
    if (previewUrl) URL.revokeObjectURL(previewUrl);
    const pUrl = URL.createObjectURL(selected);
    setPreviewUrl(pUrl);
    setFile(selected);
    extractText(selected);
  };

  const extractText = async (file) => {
    try {
      setLoading(true);
      const now = Date.now();
      setStartTime(now);
      setElapsed(0);
      // tick elapsed
      const tick = () => setElapsed(Math.floor((Date.now() - now) / 1000));
      const timerId = setInterval(tick, 500);
      setTextOutput("");
      setProgress({ done: 0, total: 0 });
      setSkippedPages([]);

      const bytes = await file.arrayBuffer();

      // load pdf.js dynamically
      const ensurePdfJs = () =>
        new Promise((resolve, reject) => {
          if (window.pdfjsLib) return resolve(window.pdfjsLib);
          const s = document.createElement("script");
          s.src =
            "https://cdn.jsdelivr.net/npm/pdfjs-dist@2.14.305/build/pdf.min.js";
          s.onload = () => resolve(window.pdfjsLib);
          s.onerror = reject;
          document.head.appendChild(s);
        });

      const pdfjsLib = await ensurePdfJs();
      pdfjsLib.GlobalWorkerOptions.workerSrc =
        "https://cdn.jsdelivr.net/npm/pdfjs-dist@2.14.305/build/pdf.worker.min.js";

      const loadingTask = pdfjsLib.getDocument({ data: bytes });
      const pdf = await loadingTask.promise;

      const total = pdf.numPages;
      setProgress({ done: 0, total });

      let fullText = "";
      const skipped = [];

      // dynamic loader for Tesseract (OCR) when needed
      const ensureTesseract = () =>
        new Promise((resolve, reject) => {
          if (window.Tesseract) return resolve(window.Tesseract);
          const s = document.createElement('script');
          s.src = 'https://cdn.jsdelivr.net/npm/tesseract.js@4.0.2/dist/tesseract.min.js';
          s.onload = () => resolve(window.Tesseract);
          s.onerror = (e) => reject(e);
          document.head.appendChild(s);
        });

      for (let i = 1; i <= total; i++) {
        const page = await pdf.getPage(i);
        const content = await page.getTextContent();

        // Group text items into approximate lines using y-position
        const items = content.items || [];
        let pageLines = [];

        if (items.length) {
          const linesMap = new Map();
          items.forEach((it) => {
            const transform = it.transform || [];
            const x = transform[4] || 0;
            const y = Math.round((transform[5] || 0));
            const key = y; // approximate grouping
            if (!linesMap.has(key)) linesMap.set(key, []);
            linesMap.get(key).push({ x, str: it.str });
          });

          // sort lines by y (desc) then by x
          const sortedYs = Array.from(linesMap.keys()).sort((a, b) => b - a);
          pageLines = sortedYs.map((y) =>
            linesMap
              .get(y)
              .sort((a, b) => a.x - b.x)
              .map((c) => c.str)
              .join(" ")
          );
        }

        // If no or very little selectable text found, fall back to OCR on the rendered canvas
        let ocrText = "";
        const needOcr = pageLines.length === 0 || pageLines.join(' ').split(' ').length < 3;
        if (needOcr) {
          try {
            const t = await ensureTesseract();
            // render page to canvas at a reasonable scale for OCR
            const viewport = page.getViewport({ scale: 2 });
            const canvas = document.createElement('canvas');
            canvas.width = Math.round(viewport.width);
            canvas.height = Math.round(viewport.height);
            const ctx = canvas.getContext('2d');
            await page.render({ canvasContext: ctx, viewport }).promise;

            const { data: { text: ocrResult } } = await t.recognize(canvas);
            ocrText = (ocrResult || '').trim();
            if (ocrText) {
              setOcrPages(prev => Array.from(new Set([...prev, i])));
            } else {
              skipped.push(i);
            }
          } catch (err) {
            console.warn('OCR failed for page', i, err);
            skipped.push(i);
          }
        }

        fullText += `\n\n----- Page ${i} -----\n\n`;
        if (pageLines.length) fullText += pageLines.join("\n");
        if (ocrText) {
          if (pageLines.length) fullText += "\n\n[OCR fallback]\n";
          fullText += ocrText;
        }

        setProgress((p) => ({ ...p, done: p.done + 1 }));
      }
      setSkippedPages(skipped);
      setTextOutput(fullText || "");
      clearInterval(timerId);
      setElapsed(Math.floor((Date.now() - now) / 1000));
      setStartTime(null);
    } catch (err) {
      console.error(err);
      alert("Failed to extract text.");
      setStartTime(null);
    } finally {
      setLoading(false);
    }
  };

  const downloadText = () => {
    const blob = new Blob([textOutput], { type: "text/plain" });
    const url = URL.createObjectURL(blob);

    const a = document.createElement("a");
    a.href = url;
    a.download = file.name.replace(".pdf", ".txt");
    a.click();

    URL.revokeObjectURL(url);
  };

  const copyToClipboard = async () => {
    try {
      await navigator.clipboard.writeText(textOutput);
      alert('Copied to clipboard');
    } catch (e) {
      console.error(e);
      alert('Copy failed');
    }
  };

  const clear = () => {
    setFile(null);
    setTextOutput("");
    setProgress({ done: 0, total: 0 });
    setSkippedPages([]);
    setOcrPages([]);
    if (fileInputRef.current) fileInputRef.current.value = null;
    if (previewUrl) URL.revokeObjectURL(previewUrl);
    setPreviewUrl(null);
    setShowPreview(false);
    setStartTime(null);
    setElapsed(0);
  };

  const toggleFullscreen = async () => {
    if (!cardRef.current) return;
    if (!document.fullscreenElement) {
      await cardRef.current.requestFullscreen();
    } else {
      await document.exitFullscreen();
    }
  };

  useEffect(() => {
    const onChange = () =>
      setIsFullscreen(Boolean(document.fullscreenElement));
    document.addEventListener("fullscreenchange", onChange);
    return () =>
      document.removeEventListener("fullscreenchange", onChange);
  }, []);

  // close preview fullscreen on ESC
  useEffect(() => {
    const onKey = (e) => {
      if (e.key === "Escape") setPreviewFullscreen(false);
    };
    if (previewFullscreen) document.addEventListener("keydown", onKey);
    return () => document.removeEventListener("keydown", onKey);
  }, [previewFullscreen]);

  return (
    <div
      className={`container-fluid ${
        isDark ? "bg-dark text-light" : "bg-light text-dark"
      }`}
      style={{ minHeight: "100vh", padding: "2rem" }}
    >
      <div
        ref={cardRef}
        className={`card shadow-lg border-0 mx-auto ${
          isDark ? "bg-dark text-light" : "bg-white"
        }`}
        style={{
          maxWidth: isFullscreen ? "100%" : "1200px",
          height: isFullscreen ? "100vh" : undefined
        }}
      >
        <div
          className={`card-header d-flex justify-content-between align-items-center ${
            isDark ? "bg-dark border-secondary" : "bg-light"
          }`}
        >
          <h5 className="m-0 fw-bold">
            <i className="bi bi-file-earmark-text me-2"></i>
            PDF to Text Converter
                  <small className="text-muted ms-3 d-none d-md-inline">Extract selectable text with optional OCR fallback</small>
          </h5>

          <div className="d-flex gap-2">
                  <input id="pdftotext-upload" ref={fileInputRef} type="file" accept="application/pdf" onChange={handleUpload} style={{ display: "none" }} />
                  <label htmlFor="pdftotext-upload" className="btn btn-sm btn-outline-primary">
                    <i className="bi bi-upload me-1"></i> Upload PDF
                  </label>

                  <div className="btn-group btn-group-sm">
                    <button className="btn btn-sm btn-outline-secondary" onClick={() => setShowPreview(s => !s)} title="Toggle preview">
                      <i className={showPreview ? "bi bi-eye" : "bi bi-eye-slash"}></i>
                    </button>
                    <button className="btn btn-sm btn-outline-secondary" onClick={() => setPreviewFullscreen(true)} title="Open preview fullscreen">
                      <i className="bi bi-file-earmark-play"></i>
                    </button>
                  </div>

            <button
              className="btn btn-sm btn-outline-success"
              onClick={toggleFullscreen}
            >
              <i
                className={
                  isFullscreen
                    ? "bi bi-arrows-collapse"
                    : "bi bi-arrows-fullscreen"
                }
              ></i>
            </button>
          </div>
        </div>

            <div className="card-body d-flex flex-column gap-3 p-4">
          {loading && (
            <div className="mb-3">
              <div className="d-flex justify-content-between small">
                <div>Processing {progress.done}/{progress.total}</div>
                <div>{progress.total ? Math.round((progress.done / progress.total) * 100) : 0}%</div>
              </div>
              <div className="progress mt-2" style={{height: '10px'}}>
                <div className="progress-bar bg-info" role="progressbar" style={{width: `${(progress.total? (progress.done/progress.total*100) : 0)}%`, borderRadius: 6}} aria-valuenow={progress.done} aria-valuemin="0" aria-valuemax={progress.total}></div>
              </div>
              <div className="d-flex justify-content-between small mt-1">
                <div>Elapsed: {Math.floor(elapsed/60)}:{String(elapsed%60).padStart(2,'0')}</div>
                <div>
                  {progress.done > 0 && progress.total > 0 ? (() => {
                    const avg = elapsed / progress.done;
                    const remain = Math.max(0, Math.ceil(avg * (progress.total - progress.done)));
                    return `ETA: ${Math.floor(remain/60)}:${String(remain%60).padStart(2,'0')}`;
                  })() : 'ETA: —'}
                </div>
              </div>
            </div>
          )}

          {textOutput && (
            <>
              <textarea
                className="form-control flex-grow-1"
                value={textOutput}
                readOnly
                style={{ minHeight: "500px" }}
              />
              <div className="d-flex gap-2 mt-3">
                <button className="btn btn-sm btn-primary" onClick={downloadText}>
                  <i className="bi bi-download me-1"></i> Download .txt
                </button>
                <button className="btn btn-sm btn-outline-secondary" onClick={copyToClipboard}>
                  <i className="bi bi-clipboard me-1"></i> Copy
                </button>
                <button className="btn btn-sm btn-outline-danger ms-auto" onClick={clear}>
                  <i className="bi bi-x-circle me-1"></i> Clear
                </button>
              </div>
            </>
          )}

          {previewUrl && showPreview && (
            <div className="mt-3">
              <h6 className="small">PDF Preview</h6>
              <div style={{borderRadius: 8, overflow: 'hidden', boxShadow: '0 4px 12px rgba(0,0,0,0.08)'}}>
                <iframe src={previewUrl} title="pdf-preview" className="w-100" style={{height: 220, border: 'none'}} />
              </div>
            </div>
          )}

          {previewFullscreen && previewUrl && (
            <div style={{position: 'fixed', inset: 0, background: 'rgba(0,0,0,0.85)', zIndex: 1050, display: 'flex', flexDirection: 'column'}}>
              <div style={{padding: 12, display: 'flex', gap: 8, alignItems: 'center'}}>
                <button className="btn btn-sm btn-light" onClick={() => setPreviewFullscreen(false)}>
                  <i className="bi bi-x-lg"></i>
                </button>
                <div style={{color: '#fff', fontSize: 14, marginLeft: 8}}>Preview — {file ? file.name : ''}</div>
              </div>
              <div style={{flex: 1, padding: 12}}>
                <iframe src={previewUrl} title="pdf-preview-full" style={{width: '100%', height: '100%', border: 'none', background: '#fff'}} />
              </div>
            </div>
          )}

          {!textOutput && !loading && (
            <div className="text-muted text-center">
              Upload a PDF to extract text. Image-only pages will be skipped.
            </div>
          )}

          {!loading && skippedPages.length > 0 && (
            <div className="mt-3 small">
              <div className="mb-1 text-warning">Skipped pages (no selectable text):</div>
              <div>
                {skippedPages.map((p) => (
                  <span key={p} className="badge bg-warning text-dark me-1">{p}</span>
                ))}
                {ocrPages.length > 0 && (
                  <span className="ms-2 small text-info">OCR used on pages: {ocrPages.join(', ')}</span>
                )}
              </div>
            </div>
          )}
        </div>
      </div>
    </div>
  );
}