import React, { useState, useEffect } from 'react';
import 'bootstrap/dist/css/bootstrap.min.css';
import 'bootstrap-icons/font/bootstrap-icons.css';
import { useTheme } from '../component/ThemeContext';
// import Python from './Python.jsx';
// import Java from './Java.jsx';
import C_Cpp from './C_Cpp.jsx';
// import Go from './Go.jsx';
// import Php from './Php.jsx';
// import Ruby from './Ruby.jsx';
// import Rust from './Rust.jsx';
import Sql from './Sql.jsx';
import React_Typescript from './React_Typescript.jsx';

const TERMINAL_TOOLS = [
  // { key: 'python', label: 'Python', icon: 'filetype-py', component: Python },
  // { key: 'java', label: 'Java', icon: 'filetype-java', component: Java },
  { key: 'c_cpp', label: 'C/C++', icon: 'filetype-cs', component: C_Cpp },
  // { key: 'go', label: 'Go', icon: 'filetype-go', component: Go },
  // { key: 'php', label: 'PHP', icon: 'filetype-php', component: Php },
  // { key: 'ruby', label: 'Ruby', icon: 'filetype-rb', component: Ruby },
  // { key: 'rust', label: 'Rust', icon: 'filetype-raw', component: Rust },
  { key: 'sql', label: 'SQL', icon: 'filetype-sql', component: Sql },
  { key: 'react_ts', label: 'React+TS', icon: 'filetype-tsx', component: React_Typescript },
];

function TerminalHome() {
  const { theme } = useTheme();
  const isDark = theme === 'dark';

  // Load activeModule from localStorage or default to 'home'
  const [activeModule, setActiveModule] = useState(() => {
    const saved = localStorage.getItem('terminalHome_activeModule');
    return saved || 'home';
  });
  const [sidebarOpen, setSidebarOpen] = useState(false);

  // Save activeModule to localStorage whenever it changes
  useEffect(() => {
    localStorage.setItem('terminalHome_activeModule', activeModule);
  }, [activeModule]);

  const sidebarBg = isDark ? 'rgba(30, 41, 59, 0.95)' : '#ffffff';
  const sidebarText = isDark ? '#e2e8f0' : '#1f2937';
  const sidebarBorder = isDark ? 'rgba(255,255,255,0.08)' : 'rgba(0,0,0,0.08)';
  const contentBg = isDark ? '#0f172a' : '#f9fafb';
  const cardBg = isDark ? 'rgba(30, 41, 59, 0.8)' : '#ffffff';
  const textColor = isDark ? '#e2e8f0' : '#1f2937';
  const accentColor = '#ffc107';

  const sidebarStyle = {
    width: '240px',
    height: '100vh',
    background: sidebarBg,
    borderRight: `1px solid ${sidebarBorder}`,
    color: sidebarText,
    overflowY: 'auto',
  };

  const navLinkStyle = (active) => ({
    color: active ? accentColor : sidebarText,
    background: active
      ? (isDark ? 'rgba(255,193,7,0.12)' : 'rgba(255,193,7,0.08)')
      : 'transparent',
    border: 'none',
    borderRadius: 8,
    padding: '10px 12px',
    display: 'flex',
    alignItems: 'center',
    gap: 10,
    cursor: 'pointer',
    fontSize: 14,
    fontWeight: active ? 600 : 500,
    width: '100%',
    borderLeft: active ? `3px solid ${accentColor}` : '3px solid transparent',
    marginBottom: 8,
  });

  const homeCardStyle = {
    background: cardBg,
    borderRadius: 12,
    padding: '28px 20px',
    maxWidth: 640,
    width: '100%',
    textAlign: 'center',
  };

  const renderModule = () => {
    if (activeModule === 'home') {
      return (
        <div style={homeCardStyle}>
          <i className="bi bi-terminal" style={{ fontSize: 48, color: accentColor }} />
          <h2 className="fw-bold mt-3" style={{ color: textColor }}>Terminal Hub</h2>
          <p style={{ color: isDark ? '#cbd5e1' : '#6b7280' }}>
            Terminal workflows, scripts, and helpers.
          </p>
          <p style={{ color: isDark ? '#94a3b8' : '#9ca3af', fontSize: 14 }}>
            Select a language from the sidebar to start coding.
          </p>
        </div>
      );
    }
    const tool = TERMINAL_TOOLS.find(t => t.key === activeModule);
    if (tool) {
      const Component = tool.component;
      return (
        <div style={{ width: '100%', maxWidth: 1100 }}>
          <Component />
        </div>
      );
    }
    return null;
  };

  return (
    <div style={{ display: 'flex', width: '100%', minHeight: '100vh', background: contentBg }}>
      <aside className="d-none d-md-block" style={sidebarStyle}>
        <div className="d-flex flex-column p-3">
          <button
            onClick={() => setActiveModule('home')}
            style={navLinkStyle(activeModule === 'home')}
          >
            <i className="bi bi-house" /> Home
          </button>

          {TERMINAL_TOOLS.map(tool => (
            <button
              key={tool.key}
              onClick={() => setActiveModule(tool.key)}
              style={navLinkStyle(activeModule === tool.key)}
            >
              <i className={`bi bi-${tool.icon}`} style={{ fontSize: 20, marginRight: 8 }} /> {tool.label}
            </button>
          ))}
        </div>
      </aside>

      <main style={{ flex: 1, display: 'grid', placeItems: 'center', padding: 16 }}>
        {renderModule()}
      </main>
    </div>
  );
}

export default TerminalHome;
