
import React, { useState, useRef, useEffect } from "react";
import { PDFDocument } from "pdf-lib";
import { useTheme } from "../component/ThemeContext";

export default function PdfCompress() {
  const { theme } = useTheme();
  const isDark = theme === "dark";

  const [file, setFile] = useState(null);
  const [previewUrl, setPreviewUrl] = useState(null);
  const [metadata, setMetadata] = useState(null);
  const [compressedUrl, setCompressedUrl] = useState(null);
  const [compressedSize, setCompressedSize] = useState(null);
  const [compressedBytes, setCompressedBytes] = useState(null);
  const [loading, setLoading] = useState(false);
  const [removeMetadata, setRemoveMetadata] = useState(true);
  const [quality, setQuality] = useState(0.85);
  const [progress, setProgress] = useState({ done: 0, total: 0 });

  const cardRef = useRef(null);
  const [isFullscreen, setIsFullscreen] = useState(false);

  const handleUpload = async (e) => {
    const selected = e.target.files[0];
    if (!selected || selected.type !== "application/pdf") {
      alert("Please upload a valid PDF.");
      return;
    }

    if (previewUrl) URL.revokeObjectURL(previewUrl);
    if (compressedUrl) URL.revokeObjectURL(compressedUrl);

    setFile(selected);
    setPreviewUrl(URL.createObjectURL(selected));
    setCompressedUrl(null);

    try {
      const bytes = await selected.arrayBuffer();
      const pdfDoc = await PDFDocument.load(bytes);

      setMetadata({
        name: selected.name,
        sizeKB: (selected.size / 1024).toFixed(2),
        sizeBytes: selected.size,
        pages: pdfDoc.getPageCount()
      });
    } catch (err) {
      console.error(err);
      alert("Failed to read PDF.");
    }
  };

  const compressPdf = async () => {
    if (!file) return alert("Upload a PDF first.");

    // Client-side rasterization + reassembly using pdf.js + pdf-lib
    try {
      setLoading(true);
      setProgress({ done: 0, total: 0 });

      const bytes = await file.arrayBuffer();

      // load pdf.js at runtime
      const ensurePdfJs = () =>
        new Promise((resolve, reject) => {
          if (window.pdfjsLib) return resolve(window.pdfjsLib);
          const s = document.createElement('script');
          s.src = 'https://cdn.jsdelivr.net/npm/pdfjs-dist@2.14.305/build/pdf.min.js';
          s.onload = () => resolve(window.pdfjsLib);
          s.onerror = (e) => reject(e);
          document.head.appendChild(s);
        });

      const pdfjsLib = await ensurePdfJs();
      pdfjsLib.GlobalWorkerOptions.workerSrc = 'https://cdn.jsdelivr.net/npm/pdfjs-dist@2.14.305/build/pdf.worker.min.js';

      const loadingTask = pdfjsLib.getDocument({ data: bytes });
      const pdf = await loadingTask.promise;
      const total = pdf.numPages;
      setProgress({ done: 0, total });

      const newPdf = await PDFDocument.create();

      for (let i = 1; i <= total; i++) {
        const page = await pdf.getPage(i);
        const viewport = page.getViewport({ scale: 1 });

     
        const renderViewport = page.getViewport({ scale:2 });

        const canvas = document.createElement('canvas');
        canvas.width = Math.round(renderViewport.width);
        canvas.height = Math.round(renderViewport.height);
        const ctx = canvas.getContext('2d');

        await page.render({ canvasContext: ctx, viewport: renderViewport }).promise;

        const blob = await new Promise(resolve => canvas.toBlob(resolve, 'image/jpeg', quality));
        const imgBytes = await blob.arrayBuffer();

        const embedded = await newPdf.embedJpg(imgBytes);
        const { width, height } = embedded.size();
        const pageDoc = newPdf.addPage([width, height]);
        pageDoc.drawImage(embedded, { x: 0, y: 0, width, height });

        setProgress(p => ({ ...p, done: p.done + 1 }));
      }

      if (removeMetadata) {
        newPdf.setTitle('');
        newPdf.setAuthor('');
      }

      const outBytes = await newPdf.save();
      const outBlob = new Blob([outBytes], { type: 'application/pdf' });
      if (compressedUrl) URL.revokeObjectURL(compressedUrl);
      const outUrl = URL.createObjectURL(outBlob);
      setCompressedUrl(outUrl);
      setCompressedSize((outBlob.size / 1024).toFixed(2));
      setCompressedBytes(outBlob.size);
    } catch (err) {
      console.error(err);
      alert('Compression failed.');
    } finally {
      setLoading(false);
    }
  };

  const toggleFullscreen = async () => {
    if (!cardRef.current) return;
    if (!document.fullscreenElement) {
      await cardRef.current.requestFullscreen();
    } else {
      await document.exitFullscreen();
    }
  };

  useEffect(() => {
    const onChange = () =>
      setIsFullscreen(Boolean(document.fullscreenElement));
    document.addEventListener("fullscreenchange", onChange);
    return () =>
      document.removeEventListener("fullscreenchange", onChange);
  }, []);

  const fmtBytes = (b) => {
    if (!b && b !== 0) return "—";
    if (b < 1024) return `${b} B`;
    if (b < 1024 * 1024) return `${(b / 1024).toFixed(2)} KB`;
    return `${(b / (1024 * 1024)).toFixed(2)} MB`;
  };

  return (
    <div
      className={`container-fluid ${
        isDark ? "bg-dark text-light" : "bg-light text-dark"
      }`}
      style={{ minHeight: "100vh", padding: "2rem" }}
    >
      <div
        ref={cardRef}
        className={`card shadow-lg border-0 mx-auto ${
          isDark ? "bg-dark text-light" : "bg-white"
        }`}
        style={{
          maxWidth: isFullscreen ? "100%" : "1200px",
          height: isFullscreen ? "100vh" : undefined
        }}
      >
        {/* Header */}
        <div
          className={`card-header d-flex justify-content-between align-items-center ${
            isDark ? "bg-dark border-secondary" : "bg-light"
          }`}
        >
          <h5 className="m-0 fw-bold">
            <i className="bi bi-file-zip me-2"></i>
            PDF Compressor
          </h5>

          <div className="d-flex gap-2">
            <input
              type="file"
              accept="application/pdf"
              onChange={handleUpload}
              className="form-control form-control-sm"
              style={{ width: "220px" }}
            />

            <button
              className="btn btn-sm btn-outline-success"
              onClick={toggleFullscreen}
            >
              <i
                className={
                  isFullscreen
                    ? "bi bi-arrows-collapse"
                    : "bi bi-arrows-fullscreen"
                }
              ></i>
            </button>
          </div>
        </div>

        <div className="row g-0" style={{ height: "750px" }}>
          {/* LEFT PANEL */}
          <div
            className={`col-md-4 border-end p-4 overflow-auto ${
              isDark ? "border-secondary" : ""
            }`}
          >
            {metadata ? (
              <>
                <h6 className="fw-bold">File Info</h6>
                <p>
                  <strong>Name:</strong> {metadata.name}
                </p>
                <p>
                  <strong>Pages:</strong> {metadata.pages}
                </p>
                <p>
                  <strong>Original Size:</strong> {metadata.size} KB
                </p>

                <hr />
                <div className="mb-3">
                  <label className="form-label">Quality</label>
                  <input type="range" min="0.25" max="0.95" step="0.05" value={quality} onChange={(e) => setQuality(Number(e.target.value))} className="form-range" />
                  <div className="d-flex justify-content-between small text-muted">
                    <span>Smaller file</span>
                    <span>Better quality</span>
                  </div>
                </div>

                <div className="form-check mb-3">
                  <input
                    type="checkbox"
                    className="form-check-input"
                    checked={removeMetadata}
                    onChange={() => setRemoveMetadata(!removeMetadata)}
                    id="removeMeta"
                  />
                  <label className="form-check-label" htmlFor="removeMeta">
                    Remove metadata
                  </label>
                </div>

                <button className="btn btn-primary w-100 mb-3" onClick={compressPdf} disabled={loading}>
                  {loading ? `Processing ${progress.done}/${progress.total}` : "Compress PDF"}
                </button>

                {compressedUrl && (
                  <>
                    <hr />
                    <p>
                      <strong>Original Size:</strong>{" "}
                      {metadata.sizeKB} KB ({fmtBytes(metadata.sizeBytes)})
                    </p>

                    <p>
                      <strong>Compressed Size:</strong>{" "}
                      {compressedSize} KB ({fmtBytes(compressedBytes)})
                    </p>

                    {metadata.sizeBytes && compressedBytes != null && (
                      <p className="text-success small mb-2">
                        Saved: {((metadata.sizeBytes - compressedBytes) / 1024).toFixed(2)} KB — {(((metadata.sizeBytes - compressedBytes) / metadata.sizeBytes) * 100).toFixed(1)}%
                      </p>
                    )}

                    <a
                      href={compressedUrl}
                      download={`Compressed_${metadata.name}`}
                      className="btn btn-success w-100"
                    >
                      <i className="bi bi-download me-1"></i>
                      Download Compressed PDF
                    </a>
                  </>
                )}
              </>
            ) : (
              <p className="text-muted">
                Upload a PDF to compress.
              </p>
            )}
          </div>

          {/* RIGHT PANEL - PREVIEW */}
          <div className="col-md-8 bg-secondary bg-opacity-10">
            {previewUrl ? (
              <iframe
                src={previewUrl}
                title="PDF Preview"
                className="w-100 h-100 border-0"
              />
            ) : (
              <div className="d-flex justify-content-center align-items-center h-100 text-muted">
                PDF preview will appear here
              </div>
            )}
          </div>
        </div>
      </div>
    </div>
  );
}