import React, { useState } from 'react';
import { BrowserRouter as Router, Routes, Route } from 'react-router-dom';
import { ThemeProvider, useTheme } from './component/ThemeContext';
import Sidebar from './component/Sidebar';
import Topbar from './component/Topbar';

import Home from './pages/Home';
import About from './pages/About';
import Contact from './pages/Contact';
import Error404 from './component/Error404';
import Footer from './component/Footer';
import ImageHome from './img/ImageHome';
import PdfHome from './pdf/PdfHome';
import AiHome from './AiModel/AiHome.jsx';
import LearnHome from './Learning/LearnHome.jsx';
import SocialHome from './Social/SocialHome.jsx';
import GameHome from './Game/GameHome.jsx';
import CmdHome from './CMDS/CmdHome.jsx';
import CodeHome from './Code/CodeHome.jsx';
import NoteHome from './Notes/NoteHome.jsx';
import TerminalHome from './Terminal/TerminalHome.jsx';


function ThemedLayout({ children }) {
  const { theme } = useTheme();
  const isDark = theme === 'dark';

  // keep subtle, neutral backgrounds that allow footer/topbar shadows to show
  const pageStyle = {
    minHeight: '100vh',
    background: isDark ? '#0b1320' : '#f7f9fc',
    color: isDark ? '#E6EEF8' : '#0b2140',
    transition: 'background 0.25s ease, color 0.25s ease',
  };

  return <div style={pageStyle}>{children}</div>;
}

function App() {

  const [showSidebar, setShowSidebar] = useState(false);
  return (
    <Router>
      <ThemeProvider>
        <ThemedLayout>
          <div className="d-flex">
            {showSidebar && (
              <div
                onClick={() => setShowSidebar(false)}
                style={{
                  position: 'fixed',
                  inset: 0,
                  background: 'rgba(0,0,0,0.45)',
                  zIndex: 1040,
                }}
              />
            )}

            <Sidebar show={showSidebar} setShow={setShowSidebar} />

            {/* Main content */}
            <div className="flex-grow-1">
              <Topbar
                sidebarOpen={showSidebar}
                toggleSidebar={() => setShowSidebar(prev => !prev)}
              />

              <div className='pt-5'>
                <Routes>
                  <Route path="/" element={<Home />} />
                  <Route path="/about" element={<About />} />            
                  <Route path="/contact" element={<Contact />} />  
                  <Route path="/img" element={<ImageHome />} />
                  <Route path="/pdf" element={<PdfHome />} />    
                  <Route path="/ai" element={<AiHome />} />                                            
                  <Route path="/learn" element={<LearnHome />} />
                  <Route path="/social" element={<SocialHome />} />
                  <Route path="/game" element={<GameHome />} />
                  <Route path="/cmds" element={<CmdHome />} />
                  <Route path="/code" element={<CodeHome />} />
                  <Route path="/notes" element={<NoteHome />} />
                  <Route path="/terminal" element={<TerminalHome />} />
               
                  <Route path="*" element={<Error404 />} />
                </Routes>
              </div>
              <Footer />
            </div>
          </div>
        </ThemedLayout>
      </ThemeProvider>
    </Router>
  );
}

export default App;
