import React, { useState, useRef, useEffect } from 'react';
import { useTheme } from '../component/ThemeContext';
import jsPDF from 'jspdf';

// Function to calculate SHA-256 hash from a Blob
async function sha256FromBlob(blob) {
  const buffer = await blob.arrayBuffer();
  const hash = await crypto.subtle.digest("SHA-256", buffer);
  return [...new Uint8Array(hash)]
    .map(b => b.toString(16).padStart(2, "0"))
    .join("");
}

export default function TextToPdf() {
  const { theme } = useTheme();
  const isDark = theme === 'dark';

  // State
  // Default margin set to 1.15 cm per request (separate sides)
  const [fontSize, setFontSize] = useState(12);
  const [marginTop, setMarginTop] = useState(1.15);
  const [marginRight, setMarginRight] = useState(1.15);
  const [marginBottom, setMarginBottom] = useState(1.15);
  const [marginLeft, setMarginLeft] = useState(1.15);
  const [orientation, setOrientation] = useState('p'); // 'p' or 'l'
  const [isFullscreen, setIsFullscreen] = useState(false);
  const [isGenerating, setIsGenerating] = useState(false);
  
  const editorRef = useRef(null);
  const genRef = useRef({ busy: false });

  // Ensure execCommand uses CSS styles where supported
  useEffect(() => {
    try {
      document.execCommand('styleWithCSS', false, true);
    } catch (e) { }
  }, []);

  // Small utility: remove empty spans and flatten nested spans to avoid overlapping style markup
  const cleanupFormatting = (root) => {
    if (!root) return;
    // remove empty spans
    const spans = Array.from(root.querySelectorAll('span'));
    spans.forEach(s => {
      // if span has no attributes and no meaningful text, remove it
      const hasStyle = s.getAttribute('style');
      const text = s.textContent?.trim();
      if ((!hasStyle || hasStyle.trim() === '') && (!text || text.length === 0)) {
        s.remove();
        return;
      }
      // flatten nested spans: if parent is span and both have styles, merge child into parent
      const parent = s.parentElement;
      if (parent && parent.tagName === 'SPAN') {
        // move children up into parent, preserving innerHTML
        parent.replaceChild(document.createTextNode(s.textContent), s);
      }
    });
    // merge adjacent text nodes (simple)
    const walker = document.createTreeWalker(root, NodeFilter.SHOW_TEXT, null, false);
    let node;
    while ((node = walker.nextNode())) {
      if (!node.nodeValue || node.nodeValue.trim() === '') continue;
      const next = node.nextSibling;
      if (next && next.nodeType === Node.TEXT_NODE) {
        node.nodeValue = node.nodeValue + next.nodeValue;
        next.remove();
      }
    }
  };
const savedRangeRef = useRef(null);

const saveSelection = () => {
  const sel = window.getSelection();
  if (sel && sel.rangeCount > 0) {
    savedRangeRef.current = sel.getRangeAt(0);
  }
};

const restoreSelection = () => {
  const sel = window.getSelection();
  if (savedRangeRef.current && sel) {
    sel.removeAllRanges();
    sel.addRange(savedRangeRef.current);
  }
};

const ensureBlockWrapper = () => {
  const editor = editorRef.current;
  if (!editor) return;

  if (!editor.firstChild || editor.firstChild.nodeName !== 'P') {
    const p = document.createElement('p');
    p.appendChild(document.createElement('br'));
    editor.appendChild(p);
  }
};

  // Helper: safely wrap selected content in a span with given CSS styles
  const applySpanStyleToSelection = (styleObj) => {
    const sel = window.getSelection();
    if (!sel || !sel.rangeCount) return;
    const range = sel.getRangeAt(0);
    if (range.collapsed) return; // nothing selected

    // Extract selected content
    const content = range.extractContents();
    const span = document.createElement('span');
    span.style.boxSizing = 'border-box';
    // apply provided styles
    Object.entries(styleObj || {}).forEach(([k, v]) => { span.style[k] = v; });
    span.appendChild(content);
    range.insertNode(span);

    // restore selection around newly inserted span
    sel.removeAllRanges();
    const newRange = document.createRange();
    newRange.selectNodeContents(span);
    sel.addRange(newRange);

    // refocus editor
    editorRef.current && editorRef.current.focus();
    // cleanup to avoid nested spans producing overlap in preview/output
    cleanupFormatting(editorRef.current);
  };

  useEffect(() => {
  ensureBlockWrapper();
}, []);

  // Apply toolbar actions
 const applyStyle = (cmd, value = null) => {
      editorRef.current?.focus();
      restoreSelection();                 // 👈 KEY LINE

      try {
        document.execCommand(cmd, false, value);
      } catch {}

      saveSelection();
      cleanupFormatting(editorRef.current);
    };




  // Map short orientation to jsPDF accepted value
  const mapOrientation = (o) => (o === 'l' ? 'landscape' : 'portrait');
const generatePdf = async (action = 'download') => {
  if (!editorRef.current || genRef.current.busy) return;
  genRef.current.busy = true;
  setIsGenerating(true);

  try {
    // Get plain text and basic formatting from the editor
    const editor = editorRef.current;
    const html = editor.innerHTML;
    const tempDiv = document.createElement('div');
    tempDiv.innerHTML = html;
    // Extract text content, preserving line breaks
    let text = '';
    tempDiv.childNodes.forEach(node => {
      if (node.nodeType === Node.ELEMENT_NODE && (node.tagName === 'P' || node.tagName === 'DIV')) {
        text += node.textContent + '\n';
      } else if (node.nodeType === Node.TEXT_NODE) {
        text += node.textContent;
      }
    });

    // PDF settings
    const doc = new jsPDF({
      orientation: orientation === 'l' ? 'landscape' : 'portrait',
      unit: 'cm',
      format: 'a4',
    });

    // Margins
    const left = marginLeft;
    const top = marginTop;
    const right = marginRight;
    const bottom = marginBottom;
    const pageWidth = doc.internal.pageSize.getWidth() - left - right;
    const pageHeight = doc.internal.pageSize.getHeight() - top - bottom;

    // Font size
    doc.setFont('Times', '');
    doc.setFontSize(fontSize);

    // Split text into lines that fit the page width
    const lines = doc.splitTextToSize(text, pageWidth);

    // Add text to PDF
    let y = top;
    const lineHeight = fontSize * 0.35; // approx line height in cm
    lines.forEach(line => {
      if (y + lineHeight > doc.internal.pageSize.getHeight() - bottom) {
        doc.addPage();
        y = top;
      }
      doc.text(line, left, y);
      y += lineHeight;
    });

    // Set PDF properties
    doc.setProperties({
      title: 'Generated Text PDF',
      author: 'CodingHub-Yogesh J.'
    });

    // Get the PDF as a blob for hashing
    const pdfBlobForHashing = doc.output('blob');
    const sha256Hash = await sha256FromBlob(pdfBlobForHashing);
    doc.setProperties({
      subject: `SHA-256: ${sha256Hash}`
    });

    if (action === 'preview') {
      const blobUrl = URL.createObjectURL(pdfBlobForHashing);
      window.open(blobUrl, '_blank');
    } else {
      doc.save('formatted-document.pdf');
    }
  } catch (e) {
    console.error(e);
    alert('An error occurred during PDF generation. Please check the console.');
  } finally {
    genRef.current.busy = false;
    setIsGenerating(false);
  }
};
  // New: paste handler to force plain-text paste (with fallback)
  const handlePaste = (e) => {
    if (!e.clipboardData) return; // let default if clipboardData unavailable
    e.preventDefault();
    const text = e.clipboardData.getData('text/plain');
    if (document.queryCommandSupported && document.queryCommandSupported('insertText')) {
      document.execCommand('insertText', false, text);
    } else {
      // Fallback insertion via range
      const sel = window.getSelection();
      if (!sel) return;
      const range = sel.getRangeAt(0);
      range.deleteContents();
      const tn = document.createTextNode(text);
      range.insertNode(tn);
      // move cursor after inserted text
      range.setStartAfter(tn);
      range.setEndAfter(tn);
      sel.removeAllRanges();
      sel.addRange(range);
    }
  };

  // Fullscreen container logic
  const containerStyle = isFullscreen ? {
    position: 'fixed', top: 0, left: 0, width: '100vw', height: '100vh',
    zIndex: 9999, background: isDark ? '#0f172a' : '#f8f9fa', padding: '10px'
  } : { marginTop: '20px' };

  // Editor "paper" style: responsive A4 visual size and theme-aware UI
  const paperStyle = {
    // use min() so it never exceeds viewport width on small screens
    width: orientation === 'p' ? 'min(210mm, 100%)' : 'min(297mm, 100%)',
    minHeight: '297mm',
    margin: '20px auto',
    padding: `${marginTop}cm ${marginRight}cm ${marginBottom}cm ${marginLeft}cm`,
    backgroundColor: isDark ? '#0b1320' : '#ffffff', // show dark/light paper UI while editing
    color: isDark ? '#e5e7eb' : '#000000',
    boxShadow: isDark ? '0 0 12px rgba(0,0,0,0.6)' : '0 0 15px rgba(0,0,0,0.15)',
    outline: 'none',
    fontFamily: 'Times New Roman, Times, serif',
    fontSize: `${fontSize}pt`,
    lineHeight: '1.2',
    boxSizing: 'border-box',
    display: 'block',
    maxWidth: '100%', // ensures it never grows beyond container
    overflowWrap: 'break-word',
    wordBreak: 'break-word',
    whiteSpace: 'pre-wrap'
  };

  // Card body style to prevent overlap and allow scrolling
  const cardBodyStyle = {
    backgroundColor: isDark ? '#0f172a' : '#e9ecef',
    overflow: 'auto',
    height: isFullscreen ? 'calc(100vh - 120px)' : '700px',
    padding: '12px'
  };

  return (
    <div className={`container-fluid ${isDark ? 'bg-dark text-light' : 'bg-light text-dark'}`} style={containerStyle}>
      <div className="card shadow-lg border-0 mx-auto" style={{ maxWidth: isFullscreen ? '100%' : '1000px', borderTop: '4px solid #0d6efd' }}>
        
        {/* TOOLBAR MENU */}
        <div className={`card-header d-flex flex-wrap align-items-center gap-3 py-3 ${isDark ? 'bg-dark' : 'bg-light'}`} style={{ borderBottom: `1px solid ${isDark ? '#495057' : '#dee2e6'}` }}>
          
          {/* Text Formatting Group */}
          <div className="d-flex align-items-center gap-2">
            <span className="small fw-bold" style={{ color: '#6c757d', fontSize: '0.75rem', textTransform: 'uppercase' }}>Format</span>
            <div className="btn-group" role="group">
              <button 
                className="btn btn-sm btn-outline-primary" 
                onClick={() => applyStyle('bold')} 
                title="Bold (Ctrl+B) - Select text first"
                style={{ color: '#0d6efd' }}
              >
                <i className="bi bi-type-bold"></i>
              </button>
              <button 
                className="btn btn-sm btn-outline-primary" 
                onClick={() => applyStyle('italic')} 
                title="Italic (Ctrl+I) - Select text first"
                style={{ color: '#0d6efd' }}
              >
                <i className="bi bi-type-italic"></i>
              </button>
            </div>
          </div>

          {/* Text Alignment Group */}
          <div className="d-flex align-items-center gap-2">
            <span className="small fw-bold" style={{ color: '#6c757d', fontSize: '0.75rem', textTransform: 'uppercase' }}>Align</span>
            <div className="btn-group" role="group">
              <button className="btn btn-sm btn-outline-secondary" onClick={() => applyStyle('justifyLeft')} title="Align Left"><i className="bi bi-align-left"></i></button>
              <button className="btn btn-sm btn-outline-secondary" onClick={() => applyStyle('justifyCenter')} title="Align Center"><i className="bi bi-align-center"></i></button>
              <button className="btn btn-sm btn-outline-secondary" onClick={() => applyStyle('justifyRight')} title="Align Right"><i className="bi bi-align-right"></i></button>
              <button className="btn btn-sm btn-outline-secondary" onClick={() => applyStyle('justifyFull')} title="Justify"><i className="bi bi-justify"></i></button>
            </div>
          </div>

          {/* Font Size Control */}
          <div className="d-flex align-items-center gap-2" style={{ borderLeft: `1px solid ${isDark ? '#495057' : '#dee2e6'}`, paddingLeft: '12px' }}>
            <label className="small fw-bold" style={{ color: '#6c757d', fontSize: '0.75rem', margin: 0 }}>
              <i className="bi bi-file-text me-1" style={{ color: '#0d6efd' }}></i>Font Size (pt)
            </label>
            <input
              type="number"
              className="form-control form-control-sm"
              style={{ width: '70px' }}
              value={fontSize}
              onChange={(e) => {
                const size = Number(e.target.value) || 12;
                setFontSize(size);

                // apply to selection if present, otherwise update editor default
                editorRef.current?.focus();
                restoreSelection();
                const sel = window.getSelection();
                if (!sel || sel.isCollapsed) {
                  if (editorRef.current) editorRef.current.style.fontSize = `${size}pt`;
                } else {
                  applySpanStyleToSelection({ fontSize: `${size}pt` });
                }
                saveSelection();
              }}
              title="Select text first to change only selected text. Leave unselected to change default."
              placeholder="12"
            />
          </div>

          {/* Page Margins Control */}
          <div className="d-flex align-items-center gap-2" style={{ borderLeft: `1px solid ${isDark ? '#495057' : '#dee2e6'}`, paddingLeft: '12px' }}>
            <label className="small fw-bold" style={{ color: '#6c757d', fontSize: '0.75rem', margin: 0 }}>
              <i className="bi bi-arrows-expand" me-1 style={{ color: '#198754' }}></i>Margins (cm)
            </label>
            <div className="d-flex gap-1" title="Page margins for all pages: Top, Right, Bottom, Left">
              <input 
                type="number" 
                step="0.1" 
                className="form-control form-control-sm" 
                style={{ width: '55px' }} 
                value={marginTop} 
                onChange={e => setMarginTop(Number(e.target.value))}
                placeholder="Top"
                title="Top margin"
              />
              <input 
                type="number" 
                step="0.1" 
                className="form-control form-control-sm" 
                style={{ width: '55px' }} 
                value={marginRight} 
                onChange={e => setMarginRight(Number(e.target.value))}
                placeholder="Right"
                title="Right margin"
              />
              <input 
                type="number" 
                step="0.1" 
                className="form-control form-control-sm" 
                style={{ width: '55px' }} 
                value={marginBottom} 
                onChange={e => setMarginBottom(Number(e.target.value))}
                placeholder="Bottom"
                title="Bottom margin"
              />
              <input 
                type="number" 
                step="0.1" 
                className="form-control form-control-sm" 
                style={{ width: '55px' }} 
                value={marginLeft} 
                onChange={e => setMarginLeft(Number(e.target.value))}
                placeholder="Left"
                title="Left margin"
              />
              <button 
                className="btn btn-sm btn-outline-secondary" 
                onClick={() => { setMarginTop(1.15); setMarginRight(1.15); setMarginBottom(1.15); setMarginLeft(1.15); }} 
                title="Reset all margins to 1.15 cm"
              >
                <i className="bi bi-arrow-counterclockwise"></i>
              </button>
            </div>
          </div>

          {/* Page Orientation */}
          <div className="d-flex align-items-center gap-2" style={{ borderLeft: `1px solid ${isDark ? '#495057' : '#dee2e6'}`, paddingLeft: '12px' }}>
            <label className="small fw-bold" style={{ color: '#6c757d', fontSize: '0.75rem', margin: 0 }}>
              <i className="bi bi-window-fullscreen" style={{ color: '#0dcaf0' }}></i>Page
            </label>
            <select 
              className="form-select form-select-sm" 
              style={{ width: '120px' }} 
              value={orientation} 
              onChange={(e) => setOrientation(e.target.value)}
            >
              <option value="p">Portrait</option>
              <option value="l">Landscape</option>
            </select>
          </div>

          {/* Action Group */}
          <div className="ms-auto d-flex gap-2">
            <button 
              className="btn btn-sm btn-info text-white" 
              onClick={() => generatePdf('preview')}
              title="Preview PDF in new window"
            >
              <i className="bi bi-eye"></i> Preview
            </button>
            <button 
              className="btn btn-sm btn-success text-white" 
              onClick={() => generatePdf('download')} 
              disabled={isGenerating}
              title="Download PDF file"
            >
              <i className="bi bi-download"></i> {isGenerating ? 'Exporting...' : 'Export'}
            </button>
            <button 
              className={`btn btn-sm ${isDark ? 'btn-outline-light' : 'btn-outline-dark'}`}
              onClick={() => setIsFullscreen(!isFullscreen)}
              title={isFullscreen ? 'Exit Fullscreen (Esc)' : 'Fullscreen Mode'}
            >
              <i className={`bi ${isFullscreen ? 'bi-fullscreen-exit' : 'bi-fullscreen'}`}></i>
            </button>
          </div>
        </div>

         {/* FULL SCREEN / STANDARD EDITOR */}
         <div className="card-body p-0" style={cardBodyStyle}>         
          <div
            ref={editorRef}
            contentEditable
            suppressContentEditableWarning
            onPaste={handlePaste}
            onMouseUp={saveSelection}
            onKeyUp={saveSelection}
            style={paperStyle}
          >
            <p><br /></p>
          </div>

         </div>
       </div>
     </div>
   );
  }