
import React from 'react';
import 'bootstrap/dist/css/bootstrap.min.css';
import { useTheme } from './ThemeContext';

// Social links from environment variables (set in .env file at project root)
const socials = [
  {
    id: 'github',
    href: process.env.REACT_APP_GITHUB_URL || 'https://github.com/yogeshjamnor',
    icon: 'bi-github',
    label: 'GitHub',
  },
  {
    id: 'linkedin',
    href: process.env.REACT_APP_LINKEDIN_URL || 'https://www.linkedin.com/in/yogeshjamnor/',
    icon: 'bi-linkedin',
    label: 'LinkedIn',
  },
  {
    id: 'email',
    href: `mailto:${process.env.REACT_APP_EMAIL || 'yogeshjamnor@gmail.com'}`,
    icon: 'bi-envelope',
    label: 'Email',
  },
];

function Footer() {
  const { theme } = useTheme();
  const isDark = theme === 'dark';

  const bg = isDark ? 'rgba(10,12,14,0.8)' : 'rgba(245,247,250,0.95)';
  const text = isDark ? '#E6EEF8' : '#0b2140'; // Primary text color
  const sub = isDark ? 'rgba(230,238,248,0.6)' : 'rgba(11,33,64,0.65)'; // Increased opacity for better contrast
  const border = isDark ? 'rgba(255,255,255,0.04)' : 'rgba(0,0,0,0.06)';
  const shadow = isDark ? '0 -2px 8px rgba(0,0,0,0.3)' : '0 -2px 8px rgba(0,0,0,0.04)';
  const accentColor = isDark ? '#6366f1' : '#4f46e5'; // Consistent accent color

  const footerStyle = {
    background: bg,
    color: text,
    padding: '2rem 0 1.5rem 0',
    borderTop: `1px solid ${border}`,
    boxShadow: shadow,
    backdropFilter: 'blur(6px)',
  };

  const linkStyle = {
    color: sub,
    textDecoration: 'none',
    fontSize: '0.85rem',
    transition: 'all 0.2s ease',
    cursor: 'pointer',
    wordBreak: 'break-word',
  };

  const iconStyle = {
    color: sub,
    display: 'inline-flex',
    alignItems: 'center',
    justifyContent: 'center',
    fontSize: '1.3rem',
    cursor: 'pointer',
    transition: 'all 0.2s ease',
    width: '40px',
    height: '40px',
    borderRadius: '8px',
    backgroundColor: isDark ? 'rgba(255,255,255,0.05)' : 'rgba(0,0,0,0.04)',
    minWidth: '40px',
    minHeight: '40px',
  };

  return (
    <footer style={footerStyle} aria-label="Footer">
      <div className="container-fluid px-3 px-sm-4 px-md-5">
        <div className="row g-4 g-md-3">
          {/* Left: Contact Info */}
          <div className="col-12 col-md-3 text-center text-md-start">
            <div style={{ fontSize: '0.85rem', color: sub, lineHeight: '1.6' }}>
              <div style={{ marginBottom: '0.5rem' }}>📍 <strong style={{ color: text }}>Pune, India</strong></div>
              <a
                href={`mailto:${process.env.REACT_APP_EMAIL || 'yogeshjamnor@gmail.com'}`}
                style={linkStyle}
                onMouseEnter={(e) => e.target.style.color = accentColor}
                onMouseLeave={(e) => e.target.style.color = sub}
              >
                {process.env.REACT_APP_EMAIL || 'yogeshjamnor@gmail.com'}
              </a>
            </div>
          </div>

          {/* Center: Copyright & Company */}
          <div className="col-12 col-md-6 text-center">
            <div style={{ fontSize: '0.85rem', color: sub, lineHeight: '1.5', marginBottom: '0.5rem' }}>
              &copy; {new Date().getFullYear()} <strong style={{ color: text }}>Coding Hub</strong> | Secure, developer-first tools.
            </div>
            <div style={{ fontSize: '0.8rem', color: sub, lineHeight: '1.4' }}>
              Developed by Yogesh J. &middot; {' '}
              <a
                href="/privacy"
                style={{ ...linkStyle, fontSize: '0.8rem' }}
                onMouseEnter={(e) => e.target.style.color = accentColor}
                onMouseLeave={(e) => e.target.style.color = sub}
              >
                Privacy Policy
              </a>
            </div>
          </div>

          {/* Right: Social Links */}
          <div className="col-12 col-md-3 d-flex justify-content-center justify-content-md-end gap-3">
            {socials.map(s => (
              <a
                key={s.id}
                href={s.href}
                target={s.href.startsWith('http') ? '_blank' : undefined}
                rel={s.href.startsWith('http') ? 'noopener noreferrer' : undefined}
                aria-label={s.label}
                style={iconStyle}
                onMouseEnter={(e) => {
                  e.currentTarget.style.color = accentColor;
                  e.currentTarget.style.backgroundColor = isDark ? 'rgba(99,102,241,0.15)' : 'rgba(79,70,229,0.1)';
                  e.currentTarget.style.transform = 'translateY(-2px) scale(1.05)';
                }}
                onMouseLeave={(e) => {
                  e.currentTarget.style.color = sub;
                  e.currentTarget.style.backgroundColor = isDark ? 'rgba(255,255,255,0.05)' : 'rgba(0,0,0,0.04)';
                  e.currentTarget.style.transform = 'translateY(0) scale(1)';
                }}
              >
                <i className={`bi ${s.icon}`} />
              </a>
            ))}
          </div>
        </div>
      </div>
    </footer>
  );
}

export default Footer;
