import React, { useState, useEffect ,lazy, Suspense } from 'react';
import 'bootstrap/dist/css/bootstrap.min.css';
import 'bootstrap-icons/font/bootstrap-icons.css';
import { useTheme } from '../component/ThemeContext';

/* ===== CODE MODULE IMPORTS ===== */
// No programming modules yet
const LocalAi = lazy(() => import('./LocalAi'));
const Gemini = lazy(() => import('./Gemini'));
const AiText = lazy(() => import('./AiText'));
const AiPdf = lazy(() => import('./AiPdf'));

const CODE_TOOLS = [
  // Example later:
  { key: 'local-ai', label: 'Local AI', icon: 'cpu', component: LocalAi },
  { key: 'gemini', label: 'Gemini AI', icon: 'stars', component: Gemini },
  { key: 'text-summary', label: 'Text Summary', icon: 'file-text', component: AiText },
  { key: 'pdf-analysis', label: 'PDF Analysis', icon: 'file-earmark-pdf', component: AiPdf },
];

function CodeHome() {
  const { theme } = useTheme();
  const isDark = theme === 'dark';

  const [activeModule, setActiveModule] = useState('home');
  const [sidebarOpen, setSidebarOpen] = useState(false);

  /* ===== THEME COLORS ===== */
  const sidebarBg = isDark ? 'rgba(30, 41, 59, 0.95)' : '#ffffff';
  const sidebarText = isDark ? '#e2e8f0' : '#1f2937';
  const sidebarBorder = isDark ? 'rgba(255,255,255,0.08)' : 'rgba(0,0,0,0.08)';
  const contentBg = isDark ? '#0f172a' : '#f9fafb';
  const cardBg = isDark ? 'rgba(30, 41, 59, 0.8)' : '#ffffff';
  const textColor = isDark ? '#e2e8f0' : '#1f2937';
  const accentColor = '#ffc107';

  /* ===== STYLES ===== */
  const sidebarStyle = {
    width: '240px',
    height: '100vh',
    background: sidebarBg,
    borderRight: `1px solid ${sidebarBorder}`,
    color: sidebarText,
    overflowY: 'auto',
  };

  const navLinkStyle = (active) => ({
    color: active ? accentColor : sidebarText,
    background: active
      ? (isDark ? 'rgba(255,193,7,0.12)' : 'rgba(255,193,7,0.08)')
      : 'transparent',
    border: 'none',
    borderRadius: 8,
    padding: '10px 12px',
    display: 'flex',
    alignItems: 'center',
    gap: 10,
    cursor: 'pointer',
    fontSize: 14,
    fontWeight: active ? 600 : 500,
    width: '100%',
    borderLeft: active ? `3px solid ${accentColor}` : '3px solid transparent',
    marginBottom: 8,
  });

  const iconOnlyButton = (active) => ({
    width: 56,
    height: 56,
    borderRadius: 12,
    display: 'inline-flex',
    alignItems: 'center',
    justifyContent: 'center',
    background: active
      ? (isDark ? 'rgba(255,193,7,0.12)' : 'rgba(255,193,7,0.08)')
      : 'transparent',
    color: active ? accentColor : sidebarText,
    border: active ? `1px solid ${accentColor}` : '1px solid transparent',
    cursor: 'pointer',
  });

  const homeCardStyle = {
    background: cardBg,
    borderRadius: 12,
    padding: '28px 20px',
    maxWidth: 640,
    width: '100%',
    textAlign: 'center',
  };

  const renderModule = () => {
    const tool = CODE_TOOLS.find(t => t.key === activeModule);
    if (tool) {
      const Component = tool.component;
      return (
        <div style={{ width: '100%', maxWidth: 1100 }}>
          <Component />
        </div>
      );
    }

    return (
      <div style={homeCardStyle}>
        <i className="bi bi-code-slash" style={{ fontSize: 48, color: accentColor }} />
        <h2 className="fw-bold mt-3" style={{ color: textColor }}>Code Hub</h2>
        <p style={{ color: isDark ? '#cbd5e1' : '#6b7280' }}>
          Programming references, snippets, and practice.
        </p>
        <p style={{ color: isDark ? '#94a3b8' : '#9ca3af', fontSize: 14 }}>
          No code modules added yet. Add them anytime.
        </p>
      </div>
    );
  };

  return (
    <div style={{ display: 'flex', width: '100%', minHeight: '100vh', background: contentBg }}>
      {/* Desktop Sidebar */}
      <aside className="d-none d-md-block" style={sidebarStyle}>
        <div className="d-flex flex-column p-3">
          <button
            onClick={() => setActiveModule('home')}
            style={navLinkStyle(activeModule === 'home')}
          >
            <i className="bi bi-house" /> Home
          </button>

          {CODE_TOOLS.map(tool => (
            <button
              key={tool.key}
              onClick={() => setActiveModule(tool.key)}
              style={navLinkStyle(activeModule === tool.key)}
            >
              <i className={`bi bi-${tool.icon}`} /> {tool.label}
            </button>
          ))}
        </div>
      </aside>

      {/* Main Content */}
      <main style={{ flex: 1 }}>
        <header
          style={{
            height: 56,
            display: 'flex',
            alignItems: 'center',
            padding: '0 12px',
            borderBottom: `1px solid ${sidebarBorder}`,
            background: isDark ? 'rgba(30,41,59,0.98)' : '#fff',
          }}
        >
          <button
            className="d-md-none btn"
            onClick={() => setSidebarOpen(v => !v)}
            style={{ background: 'transparent', color: sidebarText }}
          >
            <i className="bi bi-grid-3x3-gap"></i>
          </button>
          <strong style={{ color: sidebarText, marginLeft: 8 }}>
            <i className="bi bi-code-slash me-2" /> Programming
          </strong>
        </header>

        <div
          style={{
            padding: 16,
            marginBottom:70,
            minHeight: 'calc(100vh - 56px)',
            display: 'grid',
            placeItems: 'center',
          }}
        >
          {renderModule()}
        </div>
      </main>

      {/* Mobile bottom icon nav */}
      <div
        className="d-md-none"
        style={{
          position: 'fixed',
          left: 12,
          right: 12,
          bottom: 12,
          display: 'flex',
          gap: 8,
          justifyContent: 'space-between',
          padding: 8,
          background: isDark ? 'rgba(20,25,35,0.95)' : '#fff',
          borderRadius: 12,
          border: `1px solid ${sidebarBorder}`,
          zIndex: 1200,
        }}
      >
        <button
          onClick={() => setActiveModule('home')}
          style={iconOnlyButton(activeModule === 'home')}
        >
          <i className="bi bi-house" />
        </button>

        {CODE_TOOLS.map(tool => (
          <button
            key={tool.key}
            onClick={() => setActiveModule(tool.key)}
            style={iconOnlyButton(activeModule === tool.key)}
          >
            <i className={`bi bi-${tool.icon}`} />
          </button>
        ))}
      </div>
    </div>
  );
}

export default CodeHome;
