import React, { useState, useEffect } from 'react';
import { NavLink } from 'react-router-dom';
import { useTheme } from '../component/ThemeContext';
import axios from 'axios';
import AOS from 'aos';
import 'aos/dist/aos.css';
import 'bootstrap/dist/css/bootstrap.min.css';
import 'bootstrap-icons/font/bootstrap-icons.css';

export default function Contact() {
  const { theme,config } = useTheme();
  const isDark = theme === 'dark';
  const [hoveredIdx, setHoveredIdx] = useState(null);
  const [formData, setFormData] = useState({ name: '', mobileno: '', query: '', location: '' });
  const [loading, setLoading] = useState(false);
  const [message, setMessage] = useState({ type: '', text: '' });

  // Initialize AOS on mount and theme change
  useEffect(() => {
    AOS.init({
      duration: 800,
      easing: 'ease-in-out',
      once: false,
      mirror: true,
    });
    return () => AOS.refresh();
  }, [theme]);
const contactInfo = [
  {
    icon: 'bi-geo-alt-fill',
    title: 'Location',
    value: `${config?.user_info.location || 'Pune, Maharashtra, India'}`,
    link: 'https://maps.google.com/?q=Sawardari+Pune',
    bgColor: '#e7f1ff',
    bgDarkColor: '#0d3f66',
    iconColor: '#0d6efd',
    iconDarkColor: '#58a6ff',
  },
  {
    icon: 'bi-envelope-fill',
    title: 'Email',
    value: `${config?.user_info.contact?.email || 'yogeshjamnor@gmail.com'}`,
    link: `mailto:${config?.user_info.contact?.email || 'yogeshjamnor@gmail.com'}`,
    bgColor: '#e8f5e9',
    bgDarkColor: '#1c3d2b',
    iconColor: '#198754',
    iconDarkColor: '#4ade80',
  },
  {
    icon: 'bi-telephone-fill',
    title: 'Phone',
    value: `${config?.user_info.contact.phone}`,
    link: `tel:${config?.user_info.contact.phone}`,
    bgColor: '#fff3cd',
    bgDarkColor: '#4a3b13',
    iconColor: '#ffc107',
    iconDarkColor: '#facc15',
  },
];

  // Professional color scheme - Light & Dark modes (Enhanced)
  const colors = {
    light: {
      bg: '#ffffff',
      card: '#f8f9fa',
      text: '#0f172a',
      textSecondary: '#475569',
      border: '#e2e8f0',
      accent: '#3b82f6',
      accentLight: '#dbeafe',
      accentDark: '#1e40af',
      placeholder: '#6b7280',
      inputBg: '#f9fafb',
      inputBorder: '#d1d5db',
      success: '#10b981',
      error: '#ef4444',
      iframeBg: '#f3f4f6',
      iframeFilter: 'brightness(0.98) contrast(1.02)',
      // Icon colors - vibrant for primary visual, very subtle background tint
      locationIcon: '#0ea5e9',
      emailIcon: '#f59e0b',
      phoneIcon: '#10b981',
      locationBg: 'rgba(14, 165, 233, 0.08)', // Tint of icon color
      emailBg: 'rgba(245, 158, 11, 0.08)',    // Tint of icon color
      phoneBg: 'rgba(16, 185, 129, 0.08)',    // Tint of icon color
    },
    dark: {
      bg: '#0f172a',
      card: '#1e293b',
      text: '#f1f5f9',
      textSecondary: '#cbd5e1',
      border: '#334155',
      accent: '#60a5fa',
      accentLight: '#1e3a8a',
      accentDark: '#93c5fd',
      placeholder: '#9ca3af',
      inputBg: '#1e293b',
      inputBorder: '#475569',
      success: '#10b981',
      error: '#ef4444',
      iframeBg: '#1e293b',
      iframeFilter: 'brightness(0.95) contrast(1.1) invert(0.93)',
      // Icon colors - vibrant for primary visual, very subtle background tint
      locationIcon: '#38bdf8',
      emailIcon: '#fbbf24',
      phoneIcon: '#34d399',
      locationBg: 'rgba(56, 189, 248, 0.1)', // Tint of icon color
      emailBg: 'rgba(251, 191, 36, 0.1)',    // Tint of icon color
      phoneBg: 'rgba(52, 211, 153, 0.1)',    // Tint of icon color
    }
  };

  const currentColors = isDark ? colors.dark : colors.light;

  // Professional shadows that adapt to theme
  const shadows = {
    sm: isDark
      ? '0 1px 3px rgba(0, 0, 0, 0.8), 0 1px 2px rgba(0, 0, 0, 0.5)'
      : '0 1px 3px rgba(0, 0, 0, 0.12), 0 1px 2px rgba(0, 0, 0, 0.08)',
    md: isDark
      ? '0 4px 12px rgba(0, 0, 0, 0.9), 0 2px 6px rgba(0, 0, 0, 0.6)'
      : '0 4px 12px rgba(0, 0, 0, 0.15), 0 2px 8px rgba(0, 0, 0, 0.1)',
    lg: isDark
      ? '0 8px 24px rgba(0, 0, 0, 1), 0 4px 12px rgba(88, 166, 255, 0.15)'
      : '0 8px 24px rgba(0, 0, 0, 0.2), 0 4px 12px rgba(13, 110, 253, 0.15)',
    xl: isDark
      ? '0 12px 40px rgba(0, 0, 0, 1), 0 8px 20px rgba(88, 166, 255, 0.2)'
      : '0 12px 40px rgba(0, 0, 0, 0.25), 0 8px 20px rgba(13, 110, 253, 0.2)',
  };

  const cardStyle = {
    backgroundColor: currentColors.card,
    border: `1.5px solid ${currentColors.border}`,
    boxShadow: shadows.md,
    transition: 'all 0.3s cubic-bezier(0.4, 0, 0.2, 1)',
    cursor: 'pointer',
  };

  const cardHoverStyle = {
    ...cardStyle,
    boxShadow: shadows.lg,
    transform: 'translateY(-6px)',
    borderColor: currentColors.accent,
  };

  const handleInputChange = (e) => {
    const { name, value } = e.target;
    setFormData(prev => ({ ...prev, [name]: value }));
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    setLoading(true);
    setMessage({ type: '', text: '' });

    try {
      const response = await axios.post(`${config?.services.contact}`, formData, {
        headers: { 'Content-Type': 'application/json' }
      });

      if (response.status === 200 || response.status === 201) {
        setMessage({ type: 'success', text: 'Message sent successfully! I will get back to you soon.' });
        setFormData({ name: '', mobileno: '', query: '', location: 'Sawardari, Pune' });
      }
    } catch (error) {
      const errorMsg = error.response?.data?.message || 'Failed to send message. Please try again.';
      setMessage({ type: 'error', text: errorMsg });
      console.error('Error:', error);
    } finally {
      setLoading(false);
    }
  };

  return (
    <section style={{ backgroundColor: currentColors.bg, color: currentColors.text, minHeight: '100vh', paddingTop: '2rem', paddingBottom: '2rem' }} id='contact'>
      <div className='container'>
        {/* Header */}
        <div className='text-center mb-5' data-aos="fade-down">
          <h1 className='fw-bold' style={{
            color: currentColors.text,
            fontSize: '42px',
            marginBottom: '16px',
            letterSpacing: '-0.5px',
          }}>
            <i className='bi bi-chat-dots-fill me-3' style={{ color: currentColors.accent, fontSize: '48px' }}></i>Get In Touch
          </h1>
          <p style={{
            color: currentColors.textSecondary,
            fontSize: '16px',
            maxWidth: '600px',
            margin: '0 auto',
            lineHeight: '1.6',
          }}>
            Have a project in mind or want to collaborate? Reach out to us and let's create something amazing together!
          </p>
        </div>

        {/* Navigation Buttons */}
        <div className='text-center mb-5' data-aos="zoom-in" data-aos-delay="100">
          <div className='d-flex justify-content-center gap-2 flex-wrap'>
            <NavLink to='/' className='btn btn-sm' style={{
              backgroundColor: currentColors.accent,
              color: '#ffffff',
              border: 'none',
              borderRadius: '8px',
              transition: 'all 0.3s cubic-bezier(0.4, 0, 0.2, 1)',
              padding: '9px 18px',
              fontWeight: '600',
              fontSize: '16px', // Adjusted font size
              boxShadow: `0 2px 8px rgba(59, 130, 246, 0.2)`,
            }}
            onMouseEnter={(e) => {
              e.target.style.transform = 'translateY(-2px)';
              e.target.style.boxShadow = `0 6px 14px rgba(59, 130, 246, 0.35)`;
            }}
            onMouseLeave={(e) => {
              e.target.style.transform = 'translateY(0)';
              e.target.style.boxShadow = `0 2px 8px rgba(59, 130, 246, 0.2)`;
            }}>
              <i className='bi bi-house me-1' style={{ fontSize: '22px' }}></i> Home {/* Adjusted icon size */}
            </NavLink>
            <a
              href={config?.user_info.links.whatsapp}
              className='btn btn-sm'
              style={{
                backgroundColor: '#10b981',
                color: '#ffffff',
                border: 'none',
                borderRadius: '8px',
                transition: 'all 0.3s cubic-bezier(0.4, 0, 0.2, 1)',
                padding: '9px 18px',
                fontWeight: '600',
                fontSize: '16px', // Adjusted font size
                boxShadow: `0 2px 8px rgba(16, 185, 129, 0.2)`,
              }}
              target='_blank'
              rel='noopener noreferrer'
              onMouseEnter={(e) => {
                e.target.style.transform = 'translateY(-2px)';
                e.target.style.boxShadow = `0 6px 14px rgba(16, 185, 129, 0.35)`;
              }}
              onMouseLeave={(e) => {
                e.target.style.transform = 'translateY(0)';
                e.target.style.boxShadow = `0 2px 8px rgba(16, 185, 129, 0.2)`;
              }}
            >
              <i className='bi bi-whatsapp me-1' style={{ fontSize: '22px' }}></i> WhatsApp {/* Adjusted icon size */}
            </a>
            <a
              href={`mailto:${config?.user_info.email}`}
              className='btn btn-sm'
              style={{
                backgroundColor: '#ef4444',
                color: '#ffffff',
                border: 'none',
                borderRadius: '8px',
                transition: 'all 0.3s cubic-bezier(0.4, 0, 0.2, 1)',
                padding: '9px 18px',
                fontWeight: '600',
                fontSize: '16px', // Adjusted font size
                boxShadow: `0 2px 8px rgba(239, 68, 68, 0.2)`,
              }}
              onMouseEnter={(e) => {
                e.target.style.transform = 'translateY(-2px)';
                e.target.style.boxShadow = `0 6px 14px rgba(239, 68, 68, 0.35)`;
              }}
              onMouseLeave={(e) => {
                e.target.style.transform = 'translateY(0)';
                e.target.style.boxShadow = `0 2px 8px rgba(239, 68, 68, 0.2)`;
              }}
            >
              <i className='bi bi-envelope-at me-1' style={{ fontSize: '22px' }}></i> Gmail {/* Adjusted icon size */}
            </a>
            <a
              href={config?.user_info.links.linkedin}
              className='btn btn-sm'
              style={{
                backgroundColor: '#0ea5e9',
                color: '#ffffff',
                border: 'none',
                borderRadius: '8px',
                transition: 'all 0.3s cubic-bezier(0.4, 0, 0.2, 1)',
                padding: '9px 18px',
                fontWeight: '600',
                fontSize: '16px', // Adjusted font size
                boxShadow: `0 2px 8px rgba(14, 165, 233, 0.2)`,
              }}
              target='_blank'
              rel='noopener noreferrer'
              onMouseEnter={(e) => {
                e.target.style.transform = 'translateY(-2px)';
                e.target.style.boxShadow = `0 6px 14px rgba(14, 165, 233, 0.35)`;
              }}
              onMouseLeave={(e) => {
                e.target.style.transform = 'translateY(0)';
                e.target.style.boxShadow = `0 2px 8px rgba(14, 165, 233, 0.2)`;
              }}
            >
              <i className='bi bi-linkedin me-1' style={{ fontSize: '22px' }}></i> LinkedIn {/* Adjusted icon size */}
            </a>
            <a
              href={config?.user_info.links.github}
              className='btn btn-sm'
              style={{
                backgroundColor: isDark ? '#1e293b' : '#1f2937',
                color: isDark ? '#f1f5f9' : '#ffffff',
                border: `1.5px solid ${isDark ? '#60a5fa' : '#3b82f6'}`,
                borderRadius: '8px',
                transition: 'all 0.3s cubic-bezier(0.4, 0, 0.2, 1)',
                padding: '9px 18px',
                fontWeight: '600',
                fontSize: '16px', // Adjusted font size
                boxShadow: `0 2px 8px rgba(96, 165, 250, 0.15)`,
              }}
              target='_blank'
              rel='noopener noreferrer'
              onMouseEnter={(e) => {
                e.target.style.transform = 'translateY(-2px)';
                e.target.style.borderColor = currentColors.accent;
                e.target.style.boxShadow = `0 6px 14px rgba(96, 165, 250, 0.3)`;
              }}
              onMouseLeave={(e) => {
                e.target.style.transform = 'translateY(0)';
                e.target.style.borderColor = isDark ? '#60a5fa' : '#3b82f6';
                e.target.style.boxShadow = `0 2px 8px rgba(96, 165, 250, 0.15)`;
              }}
            >
              <i className='bi bi-github me-1' style={{ fontSize: '22px' }}></i> GitHub {/* Adjusted icon size */}
            </a>
          </div>
        </div>

        <div className='row g-4'>
          {/* Contact Form */}
          <div className='col-lg-6 mb-4' data-aos="fade-right" data-aos-delay="200">
            <div className='p-4 rounded-3 h-100' style={cardStyle}>
              <style>{`
                input::placeholder, textarea::placeholder {
                  color: ${currentColors.placeholder} !important;
                  opacity: 1 !important;
                  font-weight: 500 !important;
                }
              `}</style>
              <form onSubmit={handleSubmit}>
                <h5 className='mb-3 fw-bold' style={{ color: currentColors.text, fontSize: '18px' }}>
                  <i className='bi bi-pencil-square me-2' style={{ color: currentColors.accent }}></i>Send us a Message
                </h5>
                <p style={{ color: currentColors.textSecondary, fontSize: '14px', marginBottom: '20px' }}>Contact for queries, collaboration, or hiring opportunities!</p>

                {/* Success/Error Messages */}
                {message.text && (
                  <div className={`alert alert-${message.type === 'success' ? 'success' : 'danger'} mb-3`} style={{
                    backgroundColor: message.type === 'success' ? (isDark ? 'rgba(16, 185, 129, 0.1)' : 'rgba(16, 185, 129, 0.1)') : (isDark ? 'rgba(239, 68, 68, 0.1)' : 'rgba(239, 68, 68, 0.1)'),
                    color: message.type === 'success' ? currentColors.success : currentColors.error,
                    border: `1.5px solid ${message.type === 'success' ? currentColors.success : currentColors.error}`,
                    borderRadius: '8px',
                    padding: '12px 16px',
                  }}>
                    <i className={`bi ${message.type === 'success' ? 'bi-check-circle' : 'bi-exclamation-circle'} me-2`}></i>
                    {message.text}
                  </div>
                )}

                <input
                  type='text'
                  name='name'
                  className='form-control mb-3'
                  placeholder='Your name'
                  value={formData.name}
                  onChange={handleInputChange}
                  required
                  style={{
                    backgroundColor: currentColors.inputBg,
                    color: currentColors.text,
                    border: `1.5px solid ${currentColors.inputBorder}`,
                    borderRadius: '8px',
                    padding: '12px 14px',
                    fontSize: '14px',
                    transition: 'all 0.3s ease',
                    fontWeight: '500',
                  }}
                  onFocus={(e) => {
                    e.target.style.borderColor = currentColors.accent;
                    e.target.style.boxShadow = `0 0 0 3px ${currentColors.accentLight}`;
                    e.target.style.backgroundColor = isDark ? '#253549' : '#ffffff';
                  }}
                  onBlur={(e) => {
                    e.target.style.borderColor = currentColors.inputBorder;
                    e.target.style.boxShadow = 'none';
                    e.target.style.backgroundColor = currentColors.inputBg;
                  }}
                />
                <style>{`
                  input::placeholder, textarea::placeholder {
                    color: ${currentColors.placeholder} !important;
                    opacity: 0.8 !important;
                    font-weight: 500 !important;
                  }
                `}</style>
                <input
                  type='tel'
                  name='mobileno'
                  className='form-control mb-3'
                  placeholder='Your phone number'
                  value={formData.mobileno}
                  onChange={handleInputChange}
                  required
                  style={{
                    backgroundColor: currentColors.inputBg,
                    color: currentColors.text,
                    border: `1.5px solid ${currentColors.inputBorder}`,
                    borderRadius: '8px',
                    padding: '11px 14px',
                    fontSize: '14px',
                    transition: 'all 0.3s ease',
                    fontWeight: '500',
                  }}
                  onFocus={(e) => {
                    e.target.style.borderColor = currentColors.accent;
                    e.target.style.boxShadow = `0 0 0 3px ${currentColors.accentLight}`;
                    e.target.style.backgroundColor = isDark ? '#1e293b' : '#ffffff';
                  }}
                  onBlur={(e) => {
                    e.target.style.borderColor = currentColors.inputBorder;
                    e.target.style.boxShadow = 'none';
                    e.target.style.backgroundColor = currentColors.inputBg;
                  }}
                />
                <input
                  type='text'
                  name='location'
                  className='form-control mb-3'
                  placeholder='Location'
                  value={formData.location}
                  onChange={handleInputChange}
                  style={{
                    backgroundColor: currentColors.inputBg,
                    color: currentColors.text,
                    border: `1.5px solid ${currentColors.inputBorder}`,
                    borderRadius: '8px',
                    padding: '11px 14px',
                    fontSize: '14px',
                    transition: 'all 0.3s ease',
                    fontWeight: '500',
                  }}
                  onFocus={(e) => {
                    e.target.style.borderColor = currentColors.accent;
                    e.target.style.boxShadow = `0 0 0 3px ${currentColors.accentLight}`;
                    e.target.style.backgroundColor = isDark ? '#1e293b' : '#ffffff';
                  }}
                  onBlur={(e) => {
                    e.target.style.borderColor = currentColors.inputBorder;
                    e.target.style.boxShadow = 'none';
                    e.target.style.backgroundColor = currentColors.inputBg;
                  }}
                />
                <textarea
                  name='query'
                  className='form-control mb-3'
                  rows='5'
                  placeholder='Your message'
                  value={formData.query}
                  onChange={handleInputChange}
                  required
                  style={{
                    backgroundColor: currentColors.inputBg,
                    color: currentColors.text,
                    border: `1.5px solid ${currentColors.inputBorder}`,
                    borderRadius: '8px',
                    padding: '11px 14px',
                    fontSize: '14px',
                    transition: 'all 0.3s ease',
                    fontFamily: 'inherit',
                    fontWeight: '500',
                    resize: 'vertical',
                    minHeight: '140px',
                  }}
                  onFocus={(e) => {
                    e.target.style.borderColor = currentColors.accent;
                    e.target.style.boxShadow = `0 0 0 3px ${currentColors.accentLight}`;
                    e.target.style.backgroundColor = isDark ? '#1e293b' : '#ffffff';
                  }}
                  onBlur={(e) => {
                    e.target.style.borderColor = currentColors.inputBorder;
                    e.target.style.boxShadow = 'none';
                    e.target.style.backgroundColor = currentColors.inputBg;
                  }}
                ></textarea>
                <button 
                  type='submit' 
                  className='btn w-100 fw-semibold'
                  disabled={loading}
                  style={{ 
                    backgroundColor: currentColors.accent, 
                    color: '#ffffff', 
                    border: 'none',
                    borderRadius: '8px',
                    padding: '12px 20px',
                    fontSize: '15px',
                    fontWeight: '700',
                    transition: 'all 0.3s cubic-bezier(0.4, 0, 0.2, 1)',
                    opacity: loading ? 0.75 : 1,
                    cursor: loading ? 'not-allowed' : 'pointer',
                    boxShadow: `0 4px 12px rgba(59, 130, 246, 0.3)`,
                  }}
                  onMouseEnter={(e) => !loading && (
                    (e.target.style.transform = 'translateY(-2px)'),
                    (e.target.style.boxShadow = `0 8px 20px rgba(59, 130, 246, 0.4)`)
                  )}
                  onMouseLeave={(e) => !loading && (
                    (e.target.style.transform = 'translateY(0)'),
                    (e.target.style.boxShadow = `0 4px 12px rgba(59, 130, 246, 0.3)`)
                  )}
                >
                  {loading ? (
                    <>
                      <span className='spinner-border spinner-border-sm me-2' role='status' aria-hidden='true'></span>
                      Sending...
                    </>
                  ) : (
                    <>
                      <i className='bi bi-send-fill me-2'></i>Send Message
                    </>
                  )}
                </button>
              </form>
            </div>
          </div>

          {/* Google Map */}
          <div className='col-lg-6 mb-4' data-aos="fade-left" data-aos-delay="200">
            <div className='rounded-3 overflow-hidden h-100' style={{
              ...cardStyle,
              padding: 0,
              backgroundColor: currentColors.iframeBg,
            }}>
              <div style={{
                width: '100%',
                height: '100%',
                minHeight: '350px',
                filter: isDark ? currentColors.iframeFilter : 'none',
                transition: 'filter 0.3s ease',
              }}>
                <iframe
                  src="https://www.google.com/maps/embed?pb=!1m18!1m12!1m3!1d30220.767347360495!2d73.75820116902673!3d18.771577971739525!2m3!1f0!2f0!3f0!3m2!1i1024!2i768!4f13.1!3m3!1m2!1s0x3bc2b424d1182be3%3A0x7d482170f1e4fddf!2sSawardari%2C%20Maharashtra%20410501!5e0!3m2!1sen!2sin!4v1776606923566!5m2!1sen!2sin"
                  width="100%"
                  height="100%"
                  style={{
                    border: 0,
                    width: '100%',
                    height: '100%',
                    display: 'block'
                  }}
                  allowFullScreen=""
                  loading="lazy"
                  referrerPolicy="no-referrer-when-downgrade"
                  title="Sawardari Pune Map"
                ></iframe>
              </div>
            </div>
          </div>
        </div>
        <div className="row g-4 mt-2">
          {contactInfo.map((info, idx) => (
            <div
              key={idx}
              className="col-md-6 col-lg-4"
              data-aos="zoom-in"
              data-aos-delay={200 + idx * 100}
            >
              <a
                href={info.link}
                target="_blank"
                rel="noopener noreferrer"
                className="text-decoration-none"
                onMouseEnter={() => setHoveredIdx(idx)}
                onMouseLeave={() => setHoveredIdx(null)}
              >
                <div
                  className="d-flex align-items-center gap-4 h-100"
                  style={{
                    ...cardStyle,
                    ...(hoveredIdx === idx ? cardHoverStyle : {}),
                    borderRadius: '10px',
                    padding: '14px 16px',
                    minHeight: '72px', // 🔥 compact height
                  }}
                >
                  {/* LEFT ICON */}
                  <div
                    className="d-flex align-items-center justify-content-center flex-shrink-0"
                    style={{
                      width: '42px',
                      height: '42px',
                      borderRadius: '8px',
                    }}
                  >
                    <i
                      className={`bi ${info.icon}`}
                      style={{
                        fontSize: '36px',
                        color: isDark ? info.iconDarkColor : info.iconColor,
                      }}
                    />
                  </div>

                  {/* RIGHT INFO */}
                  <div className="flex-grow-1 overflow-hidden ">
                    <h6
                      className="mb-0 fw-semibold text-truncate "
                      style={{ color: currentColors.text, fontSize: '14px' }}
                    >
                      {info.title}: <span className='px-2'>{info.value}</span>
                    </h6>              
                  </div>
                </div>
              </a>
            </div>
          ))}
        </div>
        {/* Bottom CTA */}
        <div className='text-center mt-5' data-aos="fade-up" data-aos-delay="500">
          <p style={{ color: currentColors.textSecondary }}>
            I'm always open to new opportunities and interesting projects.
          </p>
          <p style={{ color: currentColors.accent }} className='fw-semibold'>
            Let's create something amazing together! ✨
          </p>
        </div>
      </div>
    </section>
  );
}
