import React, { useState } from 'react';
import 'bootstrap/dist/css/bootstrap.min.css';
import 'bootstrap-icons/font/bootstrap-icons.css';
import { useTheme } from '../component/ThemeContext';

/* ===== PDF TOOL IMPORTS (EXACT FILE NAMES) ===== */
import TextToPdf from './TextToPdf';
import ImageToPdf from './ImageToPdf';
import HtmlToPdf from './HtmlToPdf';
import PdfMerge from './PdfMerge';
import PdfSplit from './PdfSplit';
import PdfCompress from './PdfCompress';
import PdfProtect from './PdfProtect';
import PdfToText from './PdfToText';
import PdfMetadata from './PdfMetadata';

/* ===== TOOL CONFIG (EDIT HERE ONLY) ===== */
const PDF_TOOLS = [
  { key: 'text-pdf', label: 'Text → PDF', icon: 'file-earmark-text', component: TextToPdf },
  { key: 'image-pdf', label: 'Image → PDF', icon: 'file-earmark-image', component: ImageToPdf },
  { key: 'html-pdf', label: 'HTML → PDF', icon: 'filetype-html', component: HtmlToPdf },

  { key: 'merge', label: 'Merge PDF', icon: 'layers', component: PdfMerge },
  { key: 'split', label: 'Split PDF', icon: 'scissors', component: PdfSplit },
  { key: 'compress', label: 'Compress PDF', icon: 'arrows-collapse', component: PdfCompress },
  { key: 'protect', label: 'Protect PDF', icon: 'lock', component: PdfProtect },
  { key: 'to-text', label: 'PDF → Text', icon: 'card-text', component: PdfToText },
  { key: 'metadata', label: 'PDF Metadata', icon: 'info-circle', component: PdfMetadata },
];

function PdfHome() {
  const { theme } = useTheme();
  const isDark = theme === 'dark';

  const [activeModule, setActiveModule] = useState('home');
  const [sidebarOpen, setSidebarOpen] = useState(false);

  /* ===== THEME COLORS ===== */
  const sidebarBg = isDark ? 'rgba(30, 41, 59, 0.95)' : '#ffffff';
  const sidebarText = isDark ? '#e2e8f0' : '#1f2937';
  const sidebarBorder = isDark ? 'rgba(255,255,255,0.08)' : 'rgba(0,0,0,0.08)';
  const contentBg = isDark ? '#0f172a' : '#f9fafb';
  const cardBg = isDark ? 'rgba(30, 41, 59, 0.8)' : '#ffffff';
  const textColor = isDark ? '#e2e8f0' : '#1f2937';
  const accentColor = '#ffc107';

  /* ===== STYLES ===== */
  const sidebarStyle = {
    width: '240px',
    height: '100vh',
    background: sidebarBg,
    borderRight: `1px solid ${sidebarBorder}`,
    color: sidebarText,
    boxShadow: isDark ? '2px 0 8px rgba(0,0,0,0.2)' : '2px 0 8px rgba(0,0,0,0.06)',
    overflowY: 'auto',
  };

  const iconOnlyButton = (active) => ({
    width: 56,
    height: 56,
    borderRadius: 12,
    display: 'inline-flex',
    alignItems: 'center',
    justifyContent: 'center',
    background: active
      ? (isDark ? 'rgba(255,193,7,0.12)' : 'rgba(255,193,7,0.08)')
      : 'transparent',
    color: active ? accentColor : sidebarText,
    border: active ? `1px solid ${accentColor}` : '1px solid transparent',
    cursor: 'pointer',
    transition: 'transform .12s ease, background .12s ease',
  });

  const navLinkStyle = (isActive) => ({
    color: isActive ? accentColor : sidebarText,
    background: isActive
      ? (isDark ? 'rgba(255,193,7,0.12)' : 'rgba(255,193,7,0.08)')
      : 'transparent',
    border: 'none',
    borderRadius: 8,
    padding: '10px 12px',
    display: 'flex',
    alignItems: 'center',
    gap: 10,
    cursor: 'pointer',
    transition: 'all .12s ease',
    fontSize: 14,
    fontWeight: isActive ? 600 : 500,
    width: '100%',
    textAlign: 'left',
    borderLeft: isActive ? `3px solid ${accentColor}` : '3px solid transparent',
  });

  const contentAreaStyle = {
    background: contentBg,
    color: textColor,
    flex: 1,
    minHeight: '100vh', // This is for the entire main area to fill viewport height
    display: 'grid',
    placeItems: 'center', // center both axes
    padding: 16,
  };

  const homeCardStyle = {
    background: cardBg,
    borderRadius: 12,
    padding: '28px 20px',
    boxShadow: isDark ? '0 8px 28px rgba(0,0,0,0.28)' : '0 6px 20px rgba(0,0,0,0.06)',
    border: isDark ? '1px solid rgba(255,255,255,0.06)' : '1px solid rgba(0,0,0,0.04)',
    width: '100%',
    maxWidth: 640,
    textAlign: 'center',
  };

  const renderModule = () => {
    const tool = PDF_TOOLS.find(t => t.key === activeModule);
    if (tool) {
      const Component = tool.component;

      // wrap module for consistent centering & max width
      return (
        <div style={{ width: '100%', maxWidth: 1100, padding: 12 }}>
          <Component />
        </div>
      );
    }

    return (
      <div style={homeCardStyle}>
        <div style={{ marginBottom: 18 }}>
          <i className="bi bi-file-earmark-pdf" style={{ fontSize: 48, color: accentColor, opacity: 0.95 }} />
        </div>
        <h2 className="fw-bold mb-2" style={{ color: textColor }}>PDF Tools</h2>
        <p style={{ color: isDark ? '#cbd5e1' : '#6b7280', marginBottom: 8 }}>
          Select a PDF tool from the sidebar to get started.
        </p>
        <p style={{ color: isDark ? '#94a3b8' : '#9ca3af', fontSize: 14 }}>
          Convert, merge, split, compress, protect, and analyze PDF files.
        </p>
      </div>
    );
  };

  return (
    <div style={{ display: 'flex', width: '100%', minHeight: '100vh', background: contentBg }}>
      {/* Desktop Sidebar (full) */}
      <aside className="d-none d-md-block" style={sidebarStyle}>
        <div className="d-flex flex-column p-3" style={{ height: '100%' }}>
          <div
            style={{
              padding: '10px 8px',
              marginBottom: 12,
              textAlign: 'center',
              color: accentColor,
              fontWeight: 700,
              letterSpacing: 0.3,
            }}
          >
            <i className="bi bi-file-earmark-pdf me-2" /> PDF Tools
          </div>

          <nav className="flex-grow-1" aria-label="PDF tools">
            <button
              onClick={() => setActiveModule('home')}
              style={{ ...navLinkStyle(activeModule === 'home'), marginBottom: 8 }}
              title="Home"
            >
              <i className="bi bi-house" style={{ fontSize: 18 }}></i>
              <span>Home</span>
            </button>

            {PDF_TOOLS.map(tool => (
              <button
                key={tool.key}
                onClick={() => setActiveModule(tool.key)}
                style={{ ...navLinkStyle(activeModule === tool.key), marginBottom: 8 }}
                title={tool.label}
              >
                <i className={`bi bi-${tool.icon}`} style={{ fontSize: 18 }}></i>
                <span>{tool.label}</span>
              </button>
            ))}
          </nav>

        </div>
      </aside>

      {/* Main content: centered area */}
      <main style={{ flex: 1, display: 'flex', flexDirection: 'column' }}>
        {/* Top bar with mobile toggle */}
        <header
          style={{
            height: 56, // Fixed height for header
            display: 'flex',
            alignItems: 'center',
            gap: 12,
            padding: '0 12px',
            borderBottom: `1px solid ${sidebarBorder}`,
            background: isDark ? 'rgba(30,41,59,0.98)' : '#fff',
            zIndex: 3,
          }}
        >
          <button
            className="d-md-none btn"
            onClick={() => setSidebarOpen(v => !v)}
            aria-label="Open PDF tools"
            style={{ border: 'none', background: 'transparent', color: sidebarText, fontSize: 20 }}
          >
            <i className="bi bi-grid-3x3-gap"></i>
          </button>

          <div style={{ fontWeight: 700, color: sidebarText }}>
            <i className="bi bi-file-earmark-pdf me-2" /> PDF Utilities
          </div>
        </header>

        {/* Content area: center both axes */}
        <div style={{...contentAreaStyle, minHeight: 'calc(100vh - 56px)' }}> {/* Adjusted for header height */}
          {renderModule()}
        </div>
      </main>

      {/* Mobile bottom icon nav (icon-only, always accessible on small screens) */}
      <div
        className="d-md-none"
        style={{
          position: 'fixed',
          left: 12,
          right: 12,
          bottom: 12,
          display: 'flex',
          gap: 8,
          justifyContent: 'space-between',
          padding: 8,
          background: isDark ? 'rgba(20,25,35,0.95)' : '#fff',
          borderRadius: 12,
          boxShadow: isDark ? '0 8px 30px rgba(0,0,0,0.45)' : '0 6px 20px rgba(0,0,0,0.08)',
          border: `1px solid ${sidebarBorder}`,
          zIndex: 1200,
          alignItems: 'center',
        }}
        aria-hidden={false}
      >
        {/* Home icon */}
        <button
          onClick={() => { setActiveModule('home'); setSidebarOpen(false); }}
          title="Home"
          aria-label="Home"
          style={iconOnlyButton(activeModule === 'home')}
        >
          <i className="bi bi-house" style={{ fontSize: 18 }} />
        </button>

        {/* Display a subset of tools, e.g., first 4, then a "More" button */}
        {PDF_TOOLS.slice(0, 4).map(tool => (
          <button
            key={tool.key}
            onClick={() => { setActiveModule(tool.key); setSidebarOpen(false); }}
            title={tool.label}
            aria-label={tool.label}
            style={iconOnlyButton(activeModule === tool.key)}
          >
            <i className={`bi bi-${tool.icon}`} style={{ fontSize: 18 }} />
          </button>
        ))}

        {/* more button opens full drawer */}
        <button
          onClick={() => setSidebarOpen(true)}
          title="More"
          aria-label="More tools"
          style={iconOnlyButton(false)}
        >
          <i className="bi bi-three-dots" style={{ fontSize: 18 }} />
        </button>
      </div>

      {/* Mobile drawer (full list) */}
      {sidebarOpen && (
        <>
          <div
            onClick={() => setSidebarOpen(false)}
            className="d-md-none"
            style={{
              position: 'fixed',
              inset: 0,
              background: 'rgba(0,0,0,0.45)',
              zIndex: 1190,
            }}
          />
          <div
            className="d-md-none"
            style={{
              position: 'fixed',
              right: 12,
              bottom: 80, // Accounts for bottom mobile nav
              width: 300,
              maxWidth: 'calc(100% - 24px)',
              borderRadius: 12,
              padding: 12,
              background: sidebarBg,
              boxShadow: isDark ? '0 8px 30px rgba(0,0,0,0.45)' : '0 6px 20px rgba(0,0,0,0.08)',
              zIndex: 1195,
              border: `1px solid ${sidebarBorder}`,
            }}
            aria-label="More PDF tools"
          >
            <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: 8 }}>
              <strong style={{ color: sidebarText }}>PDF Tools</strong>
              <button className="btn btn-sm" onClick={() => setSidebarOpen(false)} style={{ border: 'none', background: 'transparent', color: sidebarText }}>
                <i className="bi bi-x-lg"></i>
              </button>
            </div>

            <div style={{ display: 'grid', gridTemplateColumns: '1fr', gap: 8 }}>
              <button
                onClick={() => { setActiveModule('home'); setSidebarOpen(false); }}
                style={navLinkStyle(activeModule === 'home')}
              >
                <i className="bi bi-house" /> <span style={{ marginLeft: 8 }}>Home</span>
              </button>

              {PDF_TOOLS.map(tool => (
                <button
                  key={tool.key}
                  onClick={() => { setActiveModule(tool.key); setSidebarOpen(false); }}
                  style={navLinkStyle(activeModule === tool.key)}
                >
                  <i className={`bi bi-${tool.icon}`} /> <span style={{ marginLeft: 8 }}>{tool.label}</span>
                </button>
              ))}
            </div>
          </div>
        </>
      )}
    </div>
  );
}

export default PdfHome;
