import React, { useState, useEffect } from 'react';
import 'bootstrap/dist/css/bootstrap.min.css';
import 'bootstrap-icons/font/bootstrap-icons.css';
import { useTheme } from '../component/ThemeContext';
import { fetchCodeData, filterCodeData, normalizeCodeData } from './CodeAcess';

/* ===== TOOL CONFIG (ADD CODE MODULES HERE LATER) ===== */
const CODE_TOOLS = [
  // Example later:
  // { key: 'html', label: 'HTML', icon: 'filetype-html', component: Html },
];

function CodeHome() {
  const { theme } = useTheme();
  const isDark = theme === 'dark';

  const [activeModule, setActiveModule] = useState('home');
  const [sidebarOpen, setSidebarOpen] = useState(false);
  const [codeData, setCodeData] = useState({});
  const [search, setSearch] = useState('');
  const [loadingData, setLoadingData] = useState(true);
  const [dataSource, setDataSource] = useState('remote');
  const [error, setError] = useState(null);
  const [copiedIndex, setCopiedIndex] = useState(null);
  const copyToClipboard = async (text, index) => {
    try {
      await navigator.clipboard.writeText(text);
      setCopiedIndex(index);
      setTimeout(() => setCopiedIndex(null), 2000);
    } catch (err) {
      console.error('Failed to copy: ', err);
    }
  };

  useEffect(() => {
    const loadData = async () => {
      // Load from cache first
      const cached = localStorage.getItem('code_access_cache_v1');
      if (cached) {
        try {
          const parsedCache = JSON.parse(cached);
          const normalizedCache = normalizeCodeData(parsedCache);
          if (Object.keys(normalizedCache).length > 0) {
            setCodeData(normalizedCache);
            setDataSource('cache');
            setLoadingData(false);
            const keys = Object.keys(normalizedCache);
            if (keys.length > 0) {
              setActiveModule(keys[0]);
            }
          }
        } catch (cacheError) {
          console.error('Cache parse failed:', cacheError);
        }
      }

      // Then fetch remote
      const { data, source, error } = await fetchCodeData();
      if (Object.keys(data).length > 0) {
        setCodeData(data);
        setDataSource(source);
        setError(error);
        if (!cached || source === 'remote') {
          const keys = Object.keys(data);
          if (keys.length > 0) {
            setActiveModule(keys[0]);
          }
        }
      } else {
        setError(error);
      }
      setLoadingData(false);
    };

    loadData();
  }, []);

  /* ===== THEME COLORS ===== */
  const sidebarBg = isDark ? 'rgba(30, 41, 59, 0.95)' : '#ffffff';
  const sidebarText = isDark ? '#e2e8f0' : '#1f2937';
  const sidebarBorder = isDark ? 'rgba(255,255,255,0.08)' : 'rgba(0,0,0,0.08)';
  const contentBg = isDark ? '#0f172a' : '#f9fafb';
  const cardBg = isDark ? 'rgba(30, 41, 59, 0.8)' : '#ffffff';
  const textColor = isDark ? '#e2e8f0' : '#1f2937';
  const accentColor = '#ffc107';

  /* ===== STYLES ===== */
  const sidebarStyle = {
    width: '240px',
    height: '100vh',
    background: sidebarBg,
    borderRight: `1px solid ${sidebarBorder}`,
    color: sidebarText,
    overflowY: 'auto',
  };

  const navLinkStyle = (active) => ({
    color: active ? accentColor : sidebarText,
    background: active
      ? (isDark ? 'rgba(255,193,7,0.12)' : 'rgba(255,193,7,0.08)')
      : 'transparent',
    border: 'none',
    borderRadius: 8,
    padding: '10px 12px',
    display: 'flex',
    alignItems: 'center',
    gap: 10,
    cursor: 'pointer',
    fontSize: 14,
    fontWeight: active ? 600 : 500,
    width: '100%',
    borderLeft: active ? `3px solid ${accentColor}` : '3px solid transparent',
    marginBottom: 8,
  });

  const iconOnlyButton = (active) => ({
    width: 56,
    height: 56,
    borderRadius: 12,
    display: 'inline-flex',
    alignItems: 'center',
    justifyContent: 'center',
    background: active
      ? (isDark ? 'rgba(255,193,7,0.12)' : 'rgba(255,193,7,0.08)')
      : 'transparent',
    color: active ? accentColor : sidebarText,
    border: active ? `1px solid ${accentColor}` : '1px solid transparent',
    cursor: 'pointer',
  });

  const homeCardStyle = {
    background: cardBg,
    borderRadius: 12,
    padding: '28px 20px',
    maxWidth: 640,
    width: '100%',
    textAlign: 'center',
  };

  const renderModule = () => {
    if (loadingData) {
      return (
        <div style={homeCardStyle}>
          <div className="spinner-border" role="status" style={{ color: accentColor }}>
            <span className="visually-hidden">Loading...</span>
          </div>
          <p style={{ color: textColor, marginTop: 10 }}>Loading code data...</p>
        </div>
      );
    }

    if (error) {
      return (
        <div style={homeCardStyle}>
          <i className="bi bi-exclamation-triangle" style={{ fontSize: 48, color: '#dc3545' }} />
          <h2 className="fw-bold mt-3" style={{ color: textColor }}>Error Loading Data</h2>
          <p style={{ color: isDark ? '#cbd5e1' : '#6b7280' }}>{error}</p>
        </div>
      );
    }

    if (activeModule === 'home') {
      return (
        <div style={homeCardStyle}>
          <i className="bi bi-code-slash" style={{ fontSize: 48, color: accentColor }} />
          <h2 className="fw-bold mt-3" style={{ color: textColor }}>Code Hub</h2>
          <p style={{ color: isDark ? '#cbd5e1' : '#6b7280' }}>
            Programming references, snippets, and practice.
          </p>
          <p style={{ color: isDark ? '#94a3b8' : '#9ca3af', fontSize: 14 }}>
            Data source: {dataSource}
          </p>
        </div>
      );
    }

    const filteredData = filterCodeData(codeData, search);
    const categoryData = filteredData[activeModule];

    if (!categoryData) {
      return (
        <div style={homeCardStyle}>
          <p style={{ color: textColor }}>Category not found or no matches for search.</p>
        </div>
      );
    }

    return (
      <div style={{ width: '100%', maxWidth: 1100 }}>
        <h3 style={{ color: textColor, marginBottom: 20 }}>{activeModule} FAQs</h3>
        <div className="accordion" id={`accordion-${activeModule}`}>
          {Object.entries(categoryData).map(([topicName, topicData], index) => (
            <div key={topicName} className="accordion-item" style={{ background: cardBg, border: `1px solid ${sidebarBorder}`, borderRadius: 8, marginBottom: 10 }}>
              <h2 className="accordion-header" id={`heading-${index}`}>
                <button
                  className="accordion-button"
                  type="button"
                  data-bs-toggle="collapse"
                  data-bs-target={`#collapse-${index}`}
                  aria-expanded="false"
                  aria-controls={`collapse-${index}`}
                  style={{
                    background: cardBg,
                    color: textColor,
                    border: 'none',
                    fontWeight: 600,
                    borderRadius: 8,
                  }}
                >
                  {topicName}
                </button>
              </h2>
              <div
                id={`collapse-${index}`}
                className="accordion-collapse collapse"
                aria-labelledby={`heading-${index}`}
                data-bs-parent={`#accordion-${activeModule}`}
              >
                <div className="accordion-body" style={{ color: textColor }}>
                  {topicData.notes && <p style={{ marginBottom: 10 }}>{topicData.notes}</p>}
                  {topicData.code && (
                    <div style={{ position: 'relative' }}>
                      <button
                        onClick={() => copyToClipboard(topicData.code, `${activeModule}-${index}`)}
                        style={{
                          position: 'absolute',
                          top: 8,
                          right: 8,
                          background: isDark ? '#374151' : '#e5e7eb',
                          border: 'none',
                          borderRadius: 4,
                          padding: '4px 8px',
                          cursor: 'pointer',
                          fontSize: 12,
                          color: textColor,
                        }}
                        title="Copy code"
                      >
                        {copiedIndex === `${activeModule}-${index}` ? 'Copied!' : 'Copy'}
                      </button>
                      <pre style={{ background: isDark ? '#1e293b' : '#f1f5f9', padding: 12, borderRadius: 4, overflow: 'auto', fontSize: 14, paddingTop: 40 }}>
                        <code style={{ color: textColor }}>{topicData.code}</code>
                      </pre>
                    </div>
                  )}
                </div>
              </div>
            </div>
          ))}
        </div>
      </div>
    );
  };

  return (
    <div style={{ display: 'flex', width: '100%', minHeight: '100vh', background: contentBg }}>
      {/* Desktop Sidebar */}
      <aside className="d-none d-md-block" style={sidebarStyle}>
        <div className="d-flex flex-column p-3">
          <button
            onClick={() => setActiveModule('home')}
            style={navLinkStyle(activeModule === 'home')}
          >
            <i className="bi bi-house" /> Home
          </button>

          {Object.keys(codeData).map(category => (
            <button
              key={category}
              onClick={() => setActiveModule(category)}
              style={navLinkStyle(activeModule === category)}
            >
              <i className="bi bi-folder" /> {category}
            </button>
          ))}
        </div>
      </aside>

      {/* Main Content */}
      <main style={{ flex: 1 }}>
        <header
          style={{
            height: 56,
            display: 'flex',
            alignItems: 'center',
            padding: '0 12px',
            borderBottom: `1px solid ${sidebarBorder}`,
            background: isDark ? 'rgba(30,41,59,0.98)' : '#fff',
          }}
        >
          <button
            className="d-md-none btn"
            onClick={() => setSidebarOpen(v => !v)}
            style={{ background: 'transparent', color: sidebarText }}
          >
            <i className="bi bi-grid-3x3-gap"></i>
          </button>
          <strong style={{ color: sidebarText, marginLeft: 8 }}>
            <i className="bi bi-code-slash me-2" /> Programming
          </strong>
          <input
            type="text"
            placeholder="Search..."
            value={search}
            onChange={(e) => setSearch(e.target.value)}
            style={{
              marginLeft: 'auto',
              padding: '4px 8px',
              borderRadius: 4,
              border: `1px solid ${sidebarBorder}`,
              background: isDark ? '#1e293b' : '#fff',
              color: textColor,
              width: 200,
            }}
          />
        </header>

        <div
          style={{
            padding: 16,
            marginBottom:70,
            minHeight: 'calc(100vh - 56px)',
            display: 'grid',
            placeItems: 'center',
          }}
        >
          {renderModule()}
        </div>
      </main>

      {/* Mobile bottom icon nav */}
      <div
        className="d-md-none"
        style={{
          position: 'fixed',
          left: 12,
          right: 12,
          bottom: 12,
          display: 'flex',
          gap: 8,
          justifyContent: 'space-between',
          padding: 8,
          background: isDark ? 'rgba(20,25,35,0.95)' : '#fff',
          borderRadius: 12,
          border: `1px solid ${sidebarBorder}`,
          zIndex: 1200,
        }}
      >
        <button
          onClick={() => setActiveModule('home')}
          style={iconOnlyButton(activeModule === 'home')}
        >
          <i className="bi bi-house" />
        </button>

        {CODE_TOOLS.map(tool => (
          <button
            key={tool.key}
            onClick={() => setActiveModule(tool.key)}
            style={iconOnlyButton(activeModule === tool.key)}
          >
            <i className={`bi bi-${tool.icon}`} />
          </button>
        ))}
      </div>
    </div>
  );
}

export default CodeHome;
