const DEFAULT_CMD_RAW_URL =
  'https://raw.githubusercontent.com/yogeshjamnor/my-website/refs/heads/main/cmd_data.json';

const CMD_CACHE_KEY = 'cmd_access_cache_v1';

const isObject = (value) => value !== null && typeof value === 'object' && !Array.isArray(value);

const sanitizeJson = (rawText) => rawText.replace(/,\s*([}\]])/g, '$1');

export const normalizeCmdData = (payload) => {
  if (!isObject(payload)) return {};

  const normalized = {};

  Object.entries(payload).forEach(([category, topicMap]) => {
    if (!isObject(topicMap)) return;

    const validTopics = {};
    Object.entries(topicMap).forEach(([topicName, topicData]) => {
      if (!isObject(topicData)) return;

      validTopics[topicName] = {
        notes: typeof topicData.notes === 'string' ? topicData.notes : '',
        code: typeof topicData.code === 'string' ? topicData.code : '',
      };
    });

    if (Object.keys(validTopics).length > 0) {
      normalized[category] = validTopics;
    }
  });

  return normalized;
};

export const fetchCmdData = async ({
  rawUrl = DEFAULT_CMD_RAW_URL,
  fallbackData = {},
  disableCache = false,
} = {}) => {
  try {
    const response = await fetch(`${rawUrl}?t=${Date.now()}`);
    if (!response.ok) {
      throw new Error(`CMD raw fetch failed: ${response.status}`);
    }

    const rawText = await response.text();
    const sanitized = sanitizeJson(rawText);
    console.log('Raw text length:', rawText.length);
    console.log('Sanitized text sample:', sanitized.substring(0, 200));
    const parsed = JSON.parse(sanitized);
    console.log('Parsed data keys:', Object.keys(parsed));
    const normalized = normalizeCmdData(parsed);

    if (Object.keys(normalized).length === 0) {
      throw new Error('CMD payload is empty or invalid');
    }

    if (!disableCache) {
      localStorage.setItem(CMD_CACHE_KEY, JSON.stringify(normalized));
    }

    return { data: normalized, source: 'remote', error: null };
  } catch (error) {
    if (!disableCache) {
      const cached = localStorage.getItem(CMD_CACHE_KEY);
      if (cached) {
        try {
          const parsedCache = JSON.parse(cached);
          const normalizedCache = normalizeCmdData(parsedCache);
          if (Object.keys(normalizedCache).length > 0) {
            return { data: normalizedCache, source: 'cache', error: null };
          }
        } catch (cacheError) {
          console.error('CMD cache parse failed:', cacheError);
        }
      }
    }

    const normalizedFallback = normalizeCmdData(fallbackData);
    return {
      data: normalizedFallback,
      source: 'fallback',
      error: error instanceof Error ? error.message : 'Unknown cmd fetch error',
    };
  }
};

export const getCmdSidebarKeys = (data) => Object.keys(normalizeCmdData(data));

export const filterCmdData = (data, query = '') => {
  const normalized = normalizeCmdData(data);
  const q = query.trim().toLowerCase();

  if (!q) return normalized;

  const filtered = {};
  Object.entries(normalized).forEach(([category, topics]) => {
    const categoryMatches = category.toLowerCase().includes(q);
    const matchedTopics = {};

    Object.entries(topics).forEach(([topicName, topicData]) => {
      const topicMatches = topicName.toLowerCase().includes(q);
      const noteMatches = topicData.notes.toLowerCase().includes(q);
      const codeMatches = topicData.code.toLowerCase().includes(q);

      if (categoryMatches || topicMatches || noteMatches || codeMatches) {
        matchedTopics[topicName] = topicData;
      }
    });

    if (Object.keys(matchedTopics).length > 0) {
      filtered[category] = matchedTopics;
    }
  });

  return filtered;
};

export { DEFAULT_CMD_RAW_URL };
