import React from 'react';
import 'bootstrap/dist/css/bootstrap.min.css';
import 'bootstrap-icons/font/bootstrap-icons.css';
import { useTheme } from '../component/ThemeContext';

export default function Youtube() {
  const { theme } = useTheme();
  const isDark = theme === 'dark';

  // Note: We use the mobile version (m.youtube.com) for a better 'webview' feel,
  // but the standard URL works too.
  const youtubeUrl = "https://m.youtube.com/embed?listType=search&list=music"; 
  // Or simply: "https://m.youtube.com"

  return (
    <div style={{
      overflow: 'hidden',
      backgroundColor: isDark ? '#fff' : '#000'
    }}>
      <iframe
        src="http://youtube-nocookie.com"
        title="YouTube WebView"
        style={{
          width: '100%',
          height: '100%',
          border: 'none',
        }}
        /* Essential permissions for a proper experience */
        allow="accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture; web-share"
        allowFullScreen
      ></iframe>
    </div>
  );
}