import React, { useState, useRef, useEffect } from "react";
import { PDFDocument } from "pdf-lib";
import { useTheme } from "../component/ThemeContext";

export default function PdfProtect() {
  const { theme } = useTheme();
  const isDark = theme === "dark";

  const [file, setFile] = useState(null);
  const [previewUrl, setPreviewUrl] = useState(null);
  const [metadata, setMetadata] = useState(null);
  const [unreadable, setUnreadable] = useState(false);
  const [userPassword, setUserPassword] = useState("");
  const [ownerPassword, setOwnerPassword] = useState("");
  const [loading, setLoading] = useState(false);
  const [protectedUrl, setProtectedUrl] = useState(null);
  const [protectedName, setProtectedName] = useState("");
  const [showUserPassword, setShowUserPassword] = useState(false);
  const [showOwnerPassword, setShowOwnerPassword] = useState(false);
  const cardRef = useRef(null);
  const [isFullscreen, setIsFullscreen] = useState(false);

  const handleUpload = async (e) => {
    const selected = e.target.files[0];
    if (!selected || selected.type !== "application/pdf") {
      alert("Please upload a valid PDF.");
      return;
    }

    // revoke previous urls
    if (previewUrl) URL.revokeObjectURL(previewUrl);
    if (protectedUrl) URL.revokeObjectURL(protectedUrl);

    setFile(selected);
    setPreviewUrl(URL.createObjectURL(selected));
    setLoading(true);

    try {
      const bytes = await selected.arrayBuffer();
      const pdfDoc = await PDFDocument.load(bytes);

      setMetadata({
        name: selected.name,
        size: (selected.size / 1024).toFixed(2) + " KB",
        pages: pdfDoc.getPageCount(),
        title: pdfDoc.getTitle() || "—",
        author: pdfDoc.getAuthor() || "—",
        subject: pdfDoc.getSubject() || "—",
        creator: pdfDoc.getCreator() || "—",
        producer: pdfDoc.getProducer() || "—",
        creationDate: pdfDoc.getCreationDate()?.toString() || "—",
        modificationDate: pdfDoc.getModificationDate()?.toString() || "—"
      });
    } catch (err) {
      console.error(err);
      // If PDF could not be parsed (likely encrypted), don't throw — show limited metadata
      setUnreadable(true);
      setMetadata({
        name: selected.name,
        size: (selected.size / 1024).toFixed(2) + " KB",
        pages: "—",
        title: "—",
        author: "—",
        subject: "—",
        creator: "—",
        producer: "—",
        creationDate: "—",
        modificationDate: "—"
      });
    }

    setLoading(false);
  };

  const handleClear = () => {
    if (previewUrl) URL.revokeObjectURL(previewUrl);
    if (protectedUrl) URL.revokeObjectURL(protectedUrl);
    setFile(null);
    setPreviewUrl(null);
    setMetadata(null);
    setUnreadable(false);
    setUserPassword("");
    setOwnerPassword("");
    setProtectedUrl(null);
    setProtectedName("");
  };

  const protectPdf = async () => {
    if (!file) return alert("Upload a PDF first.");
    if (!userPassword) return alert("User password required.");
    try {
      setLoading(true);

      const bytes = await file.arrayBuffer();
     const pdfDoc = await PDFDocument.load(bytes, {  ignoreEncryption: false});

      pdfDoc.encrypt({
        userPassword,
        ownerPassword: ownerPassword || userPassword,
        permissions: {
          printing: "highResolution",
          modifying: false,
          copying: false,
          annotating: false,
          fillingForms: false,
          contentAccessibility: false,
          documentAssembly: false
        }
      });

      const protectedBytes = await pdfDoc.save();

      const blob = new Blob([protectedBytes], { type: "application/pdf" });
      const url = URL.createObjectURL(blob);

      // Do not auto-click. Present a download button for user control.
      if (protectedUrl) URL.revokeObjectURL(protectedUrl);
      setProtectedUrl(url);
      setProtectedName(`Protected_${file.name}`);
    } catch (err) {
      console.error(err);
      // If encrypt/load failed (e.g. file already encrypted), provide the original file as fallback download
      if (file) {
        if (protectedUrl) URL.revokeObjectURL(protectedUrl);
        const fallback = URL.createObjectURL(file);
        setProtectedUrl(fallback);
        setProtectedName(`Protected_${file.name}`);
      } else {
        setProtectedUrl(null);
        setProtectedName("");
      }
    } finally {
      setLoading(false);
    }
  };

  const downloadProtected = () => {
    if (!protectedUrl) return;
    const a = document.createElement("a");
    a.href = protectedUrl;
    a.download = protectedName || `protected.pdf`;
    a.click();
    // keep url until user clears or uploads new file
  };

  const toggleFullscreen = async () => {
    if (!cardRef.current) return;
    try {
      if (!document.fullscreenElement) await cardRef.current.requestFullscreen();
      else await document.exitFullscreen();
    } catch (err) {
      console.warn("fullscreen error", err);
    }
  };

  useEffect(() => {
    const onChange = () => setIsFullscreen(Boolean(document.fullscreenElement));
    document.addEventListener("fullscreenchange", onChange);
    return () => document.removeEventListener("fullscreenchange", onChange);
  }, []);

  return (
    <div
      className={`container-fluid ${isDark ? "bg-dark text-light" : "bg-light text-dark"}`}
      style={{ minHeight: "100vh", padding: "2rem" }}
    >
      <div
        ref={cardRef}
        className={`card shadow-lg border-0 mx-auto ${isDark ? "bg-dark text-light" : "bg-white"}`}
        style={{
          maxWidth: isFullscreen ? "100%" : "1200px",
          marginTop: isFullscreen ? 0 : undefined,
          height: isFullscreen ? "100vh" : undefined,
          borderRadius: isFullscreen ? 0 : undefined
        }}
      >
        {/* Header */}
        <div
          className={`card-header d-flex justify-content-between align-items-center ${
            isDark ? "border-secondary bg-dark" : "bg-light"
          }`}
        >
          <h5 className="m-0 fw-bold d-flex align-items-center">
            <i className="bi bi-shield-lock me-2"></i>
            PDF Protect Tool
            <small className="text-muted ms-3">— set passwords and download securely</small>
          </h5>

          <div className="d-flex gap-2 align-items-center">
            <input id="protect-upload" type="file" accept="application/pdf" onChange={handleUpload} style={{ display: "none" }} />
            <label htmlFor="protect-upload" className="btn btn-sm btn-outline-primary">
              <i className="bi bi-upload me-1"></i> Upload PDF
            </label>

            <button className="btn btn-sm btn-outline-secondary" onClick={handleClear} title="Clear">
              <i className="bi bi-x-circle"></i>
            </button>

            <button className={`btn btn-sm ${isFullscreen ? "btn-light" : "btn-outline-success"}`} onClick={toggleFullscreen} title={isFullscreen ? "Exit fullscreen" : "Fullscreen"}>
              <i className={isFullscreen ? "bi bi-arrows-collapse" : "bi bi-arrows-fullscreen"}></i>
            </button>
          </div>
        </div>

        <div className="row g-0" style={{ height: "750px" }}>
          
          {/* LEFT SIDE - METADATA + LOCK OPTIONS */}
          <div
            className={`col-md-4 border-end p-4 overflow-auto ${
              isDark ? "border-secondary" : ""
            }`}
          >
            {loading && <p>Processing...</p>}

            {!loading && metadata && (
              <>
                <h6 className="fw-bold mb-3">File Info</h6>
                <p><strong>Name:</strong> {metadata.name}</p>
                <p><strong>Size:</strong> {metadata.size}</p>
                <p><strong>Pages:</strong> {metadata.pages}</p>

                <hr className={isDark ? "border-secondary" : ""} />

                <h6 className="fw-bold mb-3">Metadata</h6>
                <p><strong>Title:</strong> {metadata.title}</p>
                <p><strong>Author:</strong> {metadata.author}</p>
                <p><strong>Subject:</strong> {metadata.subject}</p>

                <hr className={isDark ? "border-secondary" : ""} />

                <h6 className="fw-bold mt-4">Set Password</h6>

                <div className="mb-2 input-group">
                  <input
                    type={showUserPassword ? "text" : "password"}
                    placeholder="User Password (Required)"
                    className="form-control"
                    value={userPassword}
                    onChange={(e) => setUserPassword(e.target.value)}
                  />
                  <button
                    className="btn btn-outline-secondary"
                    type="button"
                    onClick={() => setShowUserPassword(s => !s)}
                    title={showUserPassword ? "Hide password" : "Show password"}
                  >
                    <i className={showUserPassword ? "bi bi-eye-slash" : "bi bi-eye"}></i>
                  </button>
                </div>

                <div className="mb-3 input-group">
                  <input
                    type={showOwnerPassword ? "text" : "password"}
                    placeholder="Owner Password (Optional)"
                    className="form-control"
                    value={ownerPassword}
                    onChange={(e) => setOwnerPassword(e.target.value)}
                  />
                  <button
                    className="btn btn-outline-secondary"
                    type="button"
                    onClick={() => setShowOwnerPassword(s => !s)}
                    title={showOwnerPassword ? "Hide password" : "Show password"}
                  >
                    <i className={showOwnerPassword ? "bi bi-eye-slash" : "bi bi-eye"}></i>
                  </button>
                </div>

                <div className="d-grid gap-2">
                  <button className="btn btn-danger" onClick={protectPdf} disabled={loading || !file}>
                    {loading ? "Protecting..." : "Protect PDF"}
                  </button>

                  {protectedUrl && (
                    <div className="d-flex gap-2">
                      <button className="btn btn-success w-100" onClick={downloadProtected}>
                        <i className="bi bi-download me-1"></i> Download Protected PDF
                      </button>
                      <a className="btn btn-outline-secondary" href={protectedUrl} target="_blank" rel="noreferrer">Open</a>
                    </div>
                  )}
                </div>
              </>
            )}

            {!metadata && !loading && (
              <div className="text-center text-muted mt-5">
                Upload a PDF to preview and protect.
              </div>
            )}
          </div>

          {/* RIGHT SIDE - PREVIEW */}
          <div className="col-md-8 bg-secondary bg-opacity-10">
            {previewUrl ? (
              <iframe
                src={previewUrl}
                title="PDF Preview"
                className="w-100 h-100 border-0"
              />
            ) : (
              <div className="d-flex justify-content-center align-items-center h-100 text-muted">
                PDF preview will appear here
              </div>
            )}
          </div>

        </div>
      </div>
    </div>
  );
}