import React ,{useState}from 'react'


export default function News() {
  const [query, setQuery] = useState('');
  const [newsData, setNewsData] = useState([]);
  const fetchData = async (q) => {
    try {
      // Fetching data from different news websites
      const responses = await Promise.all([
        fetch(`https://newsapi.org/v2/everything?q=${q}&apiKey=YOUR_API_KEY`),
        fetch(`https://www.nytimes.com/api/articles/${q}/response.json`),
        fetch(`https://www.reuters.com/search/news?blob=${encodeURIComponent(q)}`)
      ]);
      const data = await Promise.all(responses.map(response => response.json()));
      // Mapping the results from each website to a common format
      const mappedResults = data.flatMap(item => {
        if (item.articles && item.results) {
          return item.articles.concat(item.results);
        } else if (item.response && item.response.docs) {
          return item.response.docs;
        }
        return [];
      });
      // Filtering and sorting the results by relevance or other criteria
      const filteredResults = mappedResults.filter(item => item.title.toLowerCase().includes(query.toLowerCase()));
      const sortedResults = filteredResults.sort((a, b) => a.relevanceScore - b.relevanceScore);
      setNewsData(sortedResults.slice(0, 10));
    } catch (error) {
      console.error('Error fetching data:', error);
    }
  };
  const handleSearch = async (e) => {
    e.preventDefault();
    fetchData(query);
  };
  return (
    <form onSubmit={handleSearch}>
      <input type="text" value={query} onChange={(e) => setQuery(e.target.value)} placeholder="Type a search term..." />
      {newsData.length > 0 ? (
        <div>
          {newsData.map((item, index) => (
            <div key={index}>
              <h2>{item.title}</h2>
              <p>{item.description}</p>
              <a href={item.url} target="_blank" rel="noopener noreferrer">
                Read more
              </a>
              <br />
              <small>Source: {item.source.name || 'Unknown'}</small>
            </div>
          ))}
        </div>
      ) : (
        <p>No results found.</p>
      )}
    </form>
  );
};
