import React, { useEffect, useState } from "react";
import { useTheme } from "../component/ThemeContext";

const starterCode = `#include <iostream>

int main() {
  std::cout << "Hello, C++ from the browser!" << std::endl;
  return 0;
}`;

const C_Cpp = () => {
	const { theme } = useTheme();
	const isDark = theme === "dark";
	const [code, setCode] = useState(starterCode);
	const [stdin, setStdin] = useState("5\n7\n");
	const [output, setOutput] = useState("Loading C/C++ WASM toolchain...");
	const [runnerReady, setRunnerReady] = useState(false);
	const [isRunning, setIsRunning] = useState(false);

	useEffect(() => {
		let mounted = true;

		(async () => {
			try {
				await import("@chriskoch/cpp-wasm");
				await window.CPP_READY;
				if (mounted) {
					setRunnerReady(true);
					setOutput("C/C++ runner ready. Click Run Code to compile and execute.");
				}
			} catch (error) {
				if (mounted) {
					setOutput(`Failed to load C/C++ toolchain.\n${error?.message || String(error)}`);
				}
			}
		})();

		return () => {
			mounted = false;
		};
	}, []);

	const runCode = async () => {
		if (!runnerReady || isRunning) return;

		setIsRunning(true);
		setOutput("Compiling and running...");
		window.CPP_OUTPUT = "";

		try {
			window.CPP.memfs.setStdinStr(stdin);
			await window.CPP.compileLinkRun(code);
			const result = (window.CPP_OUTPUT || "").trim();
			setOutput(result || "Program finished with no output.");
		} catch (error) {
			const compilerOutput = (window.CPP_OUTPUT || "").trim();
			const errorMessage = error?.message || String(error);
			setOutput(compilerOutput ? `${compilerOutput}\n${errorMessage}` : errorMessage);
		} finally {
			setIsRunning(false);
		}
	};

	return (
		<div
			className={`container-fluid mt-4 ${isDark ? "bg-dark text-light" : "bg-light text-dark"}`}
			style={{ minHeight: "80vh" }}
		>
			<h1 className="mb-2">C/C++ Code Editor</h1>
			<p className={isDark ? "text-white-50" : "text-muted"}>
				Run small C/C++ programs it Cannot run Heavy program, use ulternative tools.... Currently devleopment process
			</p>

			<div className="row g-4">
				<div className="col-md-6">
					<h3>Code Editor</h3>
					<textarea
						className={`form-control ${isDark ? "bg-secondary text-light" : "bg-light text-dark"}`}
						rows="16"
						value={code}
						onChange={(e) => setCode(e.target.value)}
						style={{ fontFamily: "monospace" }}
					/>
					<div className="d-flex gap-2 mt-3 flex-wrap">
						<button className="btn btn-primary" onClick={runCode} disabled={!runnerReady || isRunning}>
							{isRunning ? "Running..." : "Run Code"}
						</button>
						<button
							className={`btn ${isDark ? "btn-outline-light" : "btn-outline-secondary"}`}
							onClick={() => setCode(starterCode)}
							disabled={isRunning}
						>
							Reset Sample
						</button>
					</div>

					<div className="mt-4">
						<h4>Program Input</h4>
						<p className={isDark ? "text-white-50 mb-2" : "text-muted mb-2"}>
							Enter stdin values line by line, just like a real terminal input stream.
						</p>
						<textarea
							className={`form-control ${isDark ? "bg-secondary text-light" : "bg-light text-dark"}`}
							rows="6"
							value={stdin}
							onChange={(e) => setStdin(e.target.value)}
							placeholder={"Example:\n5\n7"}
							style={{ fontFamily: "monospace" }}
						/>
					</div>
				</div>

				<div className="col-md-6">
					<h3>Output</h3>
					<div
						className={`card ${isDark ? "bg-secondary text-light" : "bg-light text-dark"}`}
						style={{ minHeight: "320px" }}
					>
						<div className="card-body">
							<pre className="mb-0" style={{ whiteSpace: "pre-wrap", wordBreak: "break-word" }}>
								{output}
							</pre>
						</div>
					</div>
				</div>
			</div>
		</div>
	);
};

export default C_Cpp;
