import React, { useState, useEffect } from "react";
import { jsPDF } from "jspdf";
import { useTheme } from "../component/ThemeContext";

// Function to calculate SHA-256 hash from a Blob
async function sha256FromBlob(blob) {
  const buffer = await blob.arrayBuffer();
  const hash = await crypto.subtle.digest("SHA-256", buffer);
  return [...new Uint8Array(hash)]
    .map(b => b.toString(16).padStart(2, "0"))
    .join("");
}

export default function ImageToPdf() {
  const { theme } = useTheme();
  const isDark = theme === "dark";

  const [slides, setSlides] = useState([]);
  const [activeIndex, setActiveIndex] = useState(0);
  const [showPreview, setShowPreview] = useState(false);

  // new: margins in cm and fullscreen
  const [marginTop, setMarginTop] = useState(1.0); // Default margin 1cm
  const [marginRight, setMarginRight] = useState(1.0); // Default margin 1cm
  const [marginBottom, setMarginBottom] = useState(1.0); // Default margin 1cm
  const [marginLeft, setMarginLeft] = useState(1.0); // Default margin 1cm
  const [isFullscreen, setIsFullscreen] = useState(false);

  // useEffect to handle body overflow for fullscreen and preview modal
  useEffect(() => {
    if (isFullscreen || showPreview) {
      document.body.style.overflow = 'hidden';
    } else {
      document.body.style.overflow = ''; // Restore default
    }
    // Cleanup function
    return () => {
      document.body.style.overflow = '';
    };
  }, [isFullscreen, showPreview]); // Depend on both fullscreen and showPreview states

  /* Handle image upload */
  const handleUpload = (e) => {
    const files = Array.from(e.target.files);
    if (slides.length + files.length > 10) {
      alert("Maximum 10 images allowed");
      return;
    }

    const newSlides = files.map((file) => ({
      file,
      url: URL.createObjectURL(file),
      rotation: 0
    }));

    setSlides((prev) => [...prev, ...newSlides]);
    setActiveIndex(slides.length);
  };

  /* Paste handler - accepts image data from clipboard */
  const handlePaste = (e) => {
    if (!e.clipboardData) return;
    const items = Array.from(e.clipboardData.items || []);
    const imageItems = items.filter(it => it.kind === "file" && it.type.startsWith("image/"));
    if (!imageItems.length) return;
    imageItems.forEach(it => {
      const file = it.getAsFile();
      if (!file) return;
      const newSlide = { file, url: URL.createObjectURL(file), rotation: 0 };
      setSlides(prev => [...prev, newSlide]);
      setActiveIndex(slides.length);
    });
  };

  /* Copy single slide image to clipboard (if supported) */
  const copySlideToClipboard = async (index) => {
    if (!navigator.clipboard || !window.ClipboardItem) {
      alert("Clipboard image copy not supported in this browser");
      return;
    }
    try {
      const url = slides[index]?.url;
      if (!url) return;
      const resp = await fetch(url);
      const blob = await resp.blob();
      await navigator.clipboard.write([new ClipboardItem({ [blob.type]: blob })]);
      // minimal feedback
    } catch (err) {
      console.error(err);
      alert("Failed to copy image to clipboard");
    }
  };

  /* Rotate image */
  const rotate = (index, dir) => {
    const updated = [...slides];
    updated[index].rotation =
      (updated[index].rotation + (dir === "left" ? -90 : 90)) % 360;
    setSlides(updated);
  };

  /* Move slide */
  const moveSlide = (from, to) => {
    if (to < 0 || to >= slides.length) return;
    const updated = [...slides];
    [updated[from], updated[to]] = [updated[to], updated[from]];
    setSlides(updated);
    setActiveIndex(to);
  };

  /* Remove slide */
  const removeSlide = (index) => {
    const updated = slides.filter((_, i) => i !== index);
    setSlides(updated);
    setActiveIndex(0);
  };

  /* Export PDF - now respects margins (cm -> mm) and fits into usable area */
  const exportPdf = async () => {
    if (!slides.length) return;

    const pdf = new jsPDF("p", "mm", "a4");
    const pageWidth = 210;
    const pageHeight = 297;

    const l = marginLeft * 10;
    const r = marginRight * 10;
    const t = marginTop * 10;
    const b = marginBottom * 10;

    for (let i = 0; i < slides.length; i++) {
      if (i !== 0) pdf.addPage();

      const imgEl = new Image();
      imgEl.src = slides[i].url;
      await new Promise((res) => (imgEl.onload = res));

      let imgWidth = imgEl.width;
      let imgHeight = imgEl.height;

      const usableW = pageWidth - l - r;
      const usableH = pageHeight - t - b;

      const ratio = Math.min(usableW / imgWidth, usableH / imgHeight);

      const drawW = imgWidth * ratio;
      const drawH = imgHeight * ratio;

      const x = l + (usableW - drawW) / 2;
      const y = t + (usableH - drawH) / 2;

      pdf.addImage(
        imgEl,
        "JPEG",
        x,
        y,
        drawW,
        drawH,
        undefined,
        "FAST",
        slides[i].rotation || 0
      );
    }

    // Get the PDF as a blob to calculate its hash
    const pdfBlob = pdf.output('blob');
    const sha256Hash = await sha256FromBlob(pdfBlob);

    // Set PDF properties including the SHA-256 hash
    pdf.setProperties({
      title: "Generated Image PDF",
      author: "CodingHub-Yogesh J.",
      subject: `SHA-256: ${sha256Hash}`
    });

    pdf.save("images.pdf");
  };

  // container style respects fullscreen
  const containerStyle = isFullscreen
    ? {
        position: "fixed",
        top: 0,
        left: 0,
        width: "100vw",
        height: "100vh",
        zIndex: 99999, // Increased zIndex for maximum coverage
        padding: "1rem", // Maintain padding
        overflow: "hidden", // Main container itself should not scroll
        transition: 'background 0.25s ease, color 0.25s ease',
        background: isDark ? '#0f172a' : '#f8f9fa',
        color: isDark ? '#e5e7eb' : '#000000',
      }
    : {
        minHeight: "100vh",
        transition: 'background 0.25s ease, color 0.25s ease',
        background: isDark ? '#0f172a' : '#f8f9fa',
        color: isDark ? '#e5e7eb' : '#000000',
      };

  // Dynamic heights for slide list and preview area based on fullscreen
  // Toolbar height is approximated (e.g., 80px including padding/margin)
  const toolbarHeight = '80px';
  const containerPadding = '2rem'; // 1rem top + 1rem bottom padding on the main container
  const gapBetweenSections = '1rem'; // g-3 on row means 1rem gap (for row-gap)
  const actionButtonsHeight = '4rem'; // Estimate for action buttons and their margin (mt-3 + button height)

  const dynamicContentHeight = `calc(100vh - ${toolbarHeight} - ${containerPadding} - ${gapBetweenSections})`;

  const slideListMaxHeight = isFullscreen
    ? dynamicContentHeight
    : '70vh';

  const previewAreaMaxHeight = isFullscreen
    ? `calc(${dynamicContentHeight} - ${actionButtonsHeight})` // Subtract action button space from dynamic content height
    : '75vh'; // Original 75vh for normal mode.

  return (
    <div
      className={`container-fluid ${isDark ? "bg-dark text-light" : "bg-light text-dark"}`}
      style={containerStyle}
      onPaste={handlePaste} // paste anywhere in container
    >
      {/* Outer flex container for main content when fullscreen, ensures vertical space distribution */}
      <div className="d-flex flex-column" style={isFullscreen ? { height: '100%' } : {}}>
        <div className="d-flex flex-wrap align-items-center gap-3 mb-3 py-2 border-bottom" style={{ borderColor: isDark ? '#495057' : '#dee2e6' }}>
          <h4 className="m-0">Image → PDF (Slides)</h4>

          {/* Toolbar: file input and fullscreen toggle */}
          <div className="ms-auto d-flex flex-wrap align-items-center gap-2">
            {/* Removed Margin controls - default margin is now 1cm all sides */}
            <input
              type="file"
              accept="image/*"
              multiple
              className="form-control form-control-sm"
              style={{ flexGrow: 1, minWidth: '150px', maxWidth: '250px' }}
              onChange={handleUpload}
              title="Upload images (max 10)"
            />

            <button className={`btn btn-sm ${isDark ? 'btn-outline-light' : 'btn-outline-dark'}`} onClick={() => setIsFullscreen(s => !s)} title="Toggle Fullscreen">
              <i className={`bi ${isFullscreen ? "bi-fullscreen-exit" : "bi-fullscreen"}`}></i>
            </button>
          </div>
        </div>

        {/* Main content row - will scroll if needed in fullscreen */}
        <div className="row g-3 flex-grow-1" style={isFullscreen ? { overflowY: 'auto' } : {}}>
          {/* Slide List */}
          <div className={`col-md-3 ${isDark ? "border-secondary" : "border-end"}`} style={{ maxHeight: slideListMaxHeight, overflowY: "auto" }}>
            {slides.map((slide, index) => (
              <div
                key={index}
                className={`p-2 mb-2 rounded ${
                 index === activeIndex
                    ? isDark
                      ? "bg-primary bg-opacity-25 border border-primary"
                      : "bg-primary bg-opacity-10 border border-primary"
                    : isDark
                      ? "bg-dark border border-secondary"
                      : "bg-white border border-light"

                }`}
                onClick={() => setActiveIndex(index)}
                style={{ cursor: "pointer", transition: 'background-color 0.2s ease, border-color 0.2s ease' }}
              >
                <img
                  src={slide.url}
                  alt={`Slide ${index + 1}`}
                  style={{
                    width: "100%",
                    height: 120,
                    objectFit: "contain",
                    transform: `rotate(${slide.rotation}deg)`,
                    backgroundColor: isDark ? '#333' : '#eee',
                  }}
                  className="rounded"
                />
                <div className="d-flex justify-content-around mt-2 gap-1 flex-wrap">
                  <button className="btn btn-sm btn-outline-secondary" onClick={(e) => { e.stopPropagation(); moveSlide(index, index - 1); }} disabled={index === 0} title="Move up"><i className="bi bi-arrow-up"></i></button>
                  <button className="btn btn-sm btn-outline-secondary" onClick={(e) => { e.stopPropagation(); moveSlide(index, index + 1); }} disabled={index === slides.length - 1} title="Move down"><i className="bi bi-arrow-down"></i></button>
                  <button className="btn btn-sm btn-outline-secondary" onClick={(e) => { e.stopPropagation(); rotate(index, "left"); }} title="Rotate left"><i className="bi bi-arrow-counterclockwise"></i></button>
                  <button className="btn btn-sm btn-outline-secondary" onClick={(e) => { e.stopPropagation(); rotate(index, "right"); }} title="Rotate right"><i className="bi bi-arrow-clockwise"></i></button>
                  <button className="btn btn-sm btn-outline-danger" onClick={(e) => { e.stopPropagation(); removeSlide(index); }} title="Remove slide"><i className="bi bi-x-lg"></i></button>
                  <button className="btn btn-sm btn-outline-primary" onClick={(e) => { e.stopPropagation(); copySlideToClipboard(index); }} title="Copy image to clipboard"><i className="bi bi-clipboard"></i></button>
                </div>
              </div>
            ))}
          </div>

          {/* Slide Preview */}
          <div className="col-md-9 d-flex flex-column">
            <div className={`flex-grow-1 d-flex justify-content-center align-items-center border rounded p-3 ${isDark ? "bg-dark" : "bg-white"}`}
                style={{ minHeight: 320, maxHeight: previewAreaMaxHeight, overflow: 'auto', transition: 'background-color 0.25s ease' }}>
              {slides[activeIndex] ? (
                <img
                  src={slides[activeIndex].url}
                  alt={`Preview of slide ${activeIndex + 1}`}
                  style={{
                    maxWidth: "100%",
                    maxHeight: "100%",
                    objectFit: "contain",
                    transform: `rotate(${slides[activeIndex].rotation}deg)`,
                    backgroundColor: isDark ? '#333' : '#eee',
                  }}
                  className="rounded shadow"
                />
              ) : (
                <p className="text-muted text-center">No image selected. <br/> Paste (Ctrl+V) an image, or use the "Choose Files" button to upload one.</p>
              )}
            </div>

            {/* Action buttons */}
            <div className="text-end mt-3 d-flex justify-content-end gap-2">
              <button
                className="btn btn-outline-info text-white"
                disabled={!slides.length}
                onClick={() => setShowPreview(true)}
              >
                <i className="bi bi-eye me-1"></i> Preview
              </button>
              <button
                className="btn btn-success text-white"
                disabled={!slides.length}
                onClick={exportPdf}
              >
                <i className="bi bi-download me-1"></i> Export PDF
              </button>
            </div>
          </div>
        </div>
      </div>

      {/* FULLSCREEN PREVIEW MODAL */}
      {showPreview && (
        <div
          className={`position-fixed top-0 start-0 w-100 h-100 d-flex flex-column ${
            isDark ? "bg-dark text-light" : "bg-light text-dark"
          }`}
          style={{ zIndex: 100000, transition: 'background 0.25s ease, color 0.25s ease' }}
        >
          <div className="d-flex justify-content-between align-items-center p-3 border-bottom" style={{ borderColor: isDark ? '#495057' : '#dee2e6' }}>
            <h5 className="m-0">PDF Preview (Slide {activeIndex + 1} of {slides.length})</h5>
            <button className="btn btn-danger btn-sm" onClick={() => setShowPreview(false)}>
              <i className="bi bi-x-lg me-1"></i> Close
            </button>
          </div>

          <div className="flex-grow-1 d-flex justify-content-center align-items-center p-3" style={{ overflow: 'auto' }}>
            <img
              src={slides[activeIndex]?.url}
              alt="Full-screen preview"
              style={{
                maxWidth: "100%",
                maxHeight: "100%",
                objectFit: "contain",
                transform: `rotate(${slides[activeIndex]?.rotation}deg)`,
                backgroundColor: isDark ? '#333' : '#eee',
              }}
              className="rounded shadow"
            />
          </div>
        </div>
      )}
    </div>
  );
}
