import React, { useState, useEffect } from 'react';
import 'bootstrap/dist/css/bootstrap.min.css';
import 'bootstrap-icons/font/bootstrap-icons.css';
import { useTheme } from '../component/ThemeContext';

/* ===== LEARNING TOOL IMPORTS ===== */
import Quiz from './Quiz';
import Interview from './Interview';

/* ===== TOOL CONFIG (EDIT HERE ONLY) ===== */
const LEARN_TOOLS = [
  { key: 'quiz', label: 'Quiz', icon: 'question-circle', component: Quiz },
  { key: 'interview', label: 'Interview', icon: 'person-lines-fill', component: Interview },
  // future:
  // { key: 'notes', label: 'Notes', icon: 'journal-text', component: Notes },
];

function LearnHome() {
  const { theme } = useTheme();
  const isDark = theme === 'dark';

  // Load activeModule from localStorage or default to 'home'
  const [activeModule, setActiveModule] = useState(() => {
    const saved = localStorage.getItem('learnHome_activeModule');
    return saved || 'home';
  });
  const [sidebarOpen, setSidebarOpen] = useState(false);

  // Save activeModule to localStorage whenever it changes
  useEffect(() => {
    localStorage.setItem('learnHome_activeModule', activeModule);
  }, [activeModule]);

  /* ===== THEME COLORS ===== */
  const sidebarBg = isDark ? 'rgba(30, 41, 59, 0.95)' : '#ffffff';
  const sidebarText = isDark ? '#e2e8f0' : '#1f2937';
  const sidebarBorder = isDark ? 'rgba(255,255,255,0.08)' : 'rgba(0,0,0,0.08)';
  const contentBg = isDark ? '#0f172a' : '#f9fafb';
  const cardBg = isDark ? 'rgba(30, 41, 59, 0.8)' : '#ffffff';
  const textColor = isDark ? '#e2e8f0' : '#1f2937';
  const accentColor = '#ffc107';

  /* ===== STYLES ===== */
  const sidebarStyle = {
    width: '240px',
    height: '100vh',
    background: sidebarBg,
    borderRight: `1px solid ${sidebarBorder}`,
    color: sidebarText,
    overflowY: 'auto',
  };

  const navLinkStyle = (active) => ({
    color: active ? accentColor : sidebarText,
    background: active
      ? (isDark ? 'rgba(255,193,7,0.12)' : 'rgba(255,193,7,0.08)')
      : 'transparent',
    border: 'none',
    borderRadius: 8,
    padding: '10px 12px',
    display: 'flex',
    alignItems: 'center',
    gap: 10,
    cursor: 'pointer',
    fontSize: 14,
    fontWeight: active ? 600 : 500,
    width: '100%',
    borderLeft: active ? `3px solid ${accentColor}` : '3px solid transparent',
    marginBottom: 8,
  });

  const iconOnlyButton = (active) => ({
    width: 56,
    height: 56,
    borderRadius: 12,
    display: 'inline-flex',
    alignItems: 'center',
    justifyContent: 'center',
    background: active
      ? (isDark ? 'rgba(255,193,7,0.12)' : 'rgba(255,193,7,0.08)')
      : 'transparent',
    color: active ? accentColor : sidebarText,
    border: active ? `1px solid ${accentColor}` : '1px solid transparent',
    cursor: 'pointer',
  });

  const homeCardStyle = {
    background: cardBg,
    borderRadius: 12,
    padding: '28px 20px',
    maxWidth: 640,
    width: '100%',
    textAlign: 'center',
  };

  const renderModule = () => {
    const tool = LEARN_TOOLS.find(t => t.key === activeModule);
    if (tool) {
      const Component = tool.component;
      return (
        <div style={{ width: '100%', maxWidth: 1100 }}>
          <Component />
        </div>
      );
    }

    return (
      <div style={homeCardStyle}>
        <i className="bi bi-book-half" style={{ fontSize: 48, color: accentColor }} />
        <h2 className="fw-bold mt-3" style={{ color: textColor }}>Learning Hub</h2>
        <p style={{ color: isDark ? '#cbd5e1' : '#6b7280' }}>
          Practice quizzes and prepare for interviews.
        </p>
      </div>
    );
  };

  return (
    <div style={{ display: 'flex', width: '100%', minHeight: '100vh', background: contentBg }}>
      {/* Desktop Sidebar */}
      <aside className="d-none d-md-block" style={sidebarStyle}>
        <div className="d-flex flex-column py-5 px-3">
          <button
            onClick={() => setActiveModule('home')}
            style={navLinkStyle(activeModule === 'home')}
          >
            <i className="bi bi-house" /> Home
          </button>

          {LEARN_TOOLS.map(tool => (
            <button
              key={tool.key}
              onClick={() => setActiveModule(tool.key)}
              style={navLinkStyle(activeModule === tool.key)}
            >
              <i className={`bi bi-${tool.icon}`} /> {tool.label}
            </button>
          ))}
        </div>
      </aside>

      {/* Main Content */}
      <main style={{ flex: 1 }}>
        <header
          style={{
            height: 56,
            display: 'flex',
            alignItems: 'center',
            padding: '0 12px',
            borderBottom: `1px solid ${sidebarBorder}`,
            background: isDark ? 'rgba(30,41,59,0.98)' : '#fff',
          }}
        >
          <button
            className="d-md-none btn"
            onClick={() => setSidebarOpen(v => !v)}
            style={{ background: 'transparent', color: sidebarText }}
          >
            <i className="bi bi-grid-3x3-gap"></i>
          </button>
          <strong style={{ color: sidebarText, marginLeft: 8 }}>
            <i className="bi bi-book-half me-2" /> Learning
          </strong>
        </header>

        <div
          style={{
            padding: 16,
            minHeight: 'calc(100vh - 56px)',
            display: 'grid',
            placeItems: 'center',
          }}
        >
          {renderModule()}
        </div>
      </main>

      {/* Mobile bottom icon nav */}
      <div
        className="d-md-none"
        style={{
          position: 'fixed',
          left: 12,
          right: 12,
          bottom: 12,
          display: 'flex',
          gap: 8,
          justifyContent: 'space-between',
          padding: 8,
          background: isDark ? 'rgba(20,25,35,0.95)' : '#fff',
          borderRadius: 12,
          border: `1px solid ${sidebarBorder}`,
          zIndex: 1200,
        }}
      >
        <button
          onClick={() => { setActiveModule('home'); setSidebarOpen(false); }}
          style={iconOnlyButton(activeModule === 'home')}
        >
          <i className="bi bi-house" />
        </button>

        {LEARN_TOOLS.map(tool => (
          <button
            key={tool.key}
            onClick={() => { setActiveModule(tool.key); setSidebarOpen(false); }}
            style={iconOnlyButton(activeModule === tool.key)}
          >
            <i className={`bi bi-${tool.icon}`} />
          </button>
        ))}
      </div>
    </div>
  );
}

export default LearnHome;
