import React, { useState, useEffect } from "react";
import { useTheme } from "../component/ThemeContext";

// Simple JSON-based SQL Engine
class SimpleSQL {
	constructor() {
		this.tables = {};
		this.autoIncrement = {};
	}

	createTable(name, columns) {
		this.tables[name] = { columns, rows: [] };
		this.autoIncrement[name] = 1;
	}

	dropTable(name) {
		if (this.tables[name]) {
			delete this.tables[name];
			delete this.autoIncrement[name];
			return true;
		}
		return false;
	}

	insert(tableName, data) {
		if (!this.tables[tableName]) throw new Error(`Table ${tableName} does not exist`);
		const table = this.tables[tableName];
		
		// Handle auto-increment
		if (!data.id && table.columns.includes('id')) {
			data.id = this.autoIncrement[tableName]++;
		}
		
		table.rows.push(data);
		return true;
	}

	select(tableName, conditions = {}, columns = null) {
		if (!this.tables[tableName]) throw new Error(`Table ${tableName} does not exist`);
		const table = this.tables[tableName];
		
		let results = table.rows.filter(row => {
			return Object.keys(conditions).every(key => row[key] == conditions[key]);
		});

		if (columns && columns !== '*') {
			const cols = columns.split(',').map(c => c.trim());
			results = results.map(row => {
				const obj = {};
				cols.forEach(col => {
					if (col.includes('COUNT(*)')) obj['COUNT(*)'] = results.length;
					else obj[col] = row[col];
				});
				return obj;
			});
		}

		return { columns: columns === '*' ? table.columns : (columns ? columns.split(',').map(c => c.trim()) : table.columns), rows: results };
	}

	update(tableName, updates, conditions) {
		if (!this.tables[tableName]) throw new Error(`Table ${tableName} does not exist`);
		const table = this.tables[tableName];
		
		let count = 0;
		table.rows = table.rows.map(row => {
			if (Object.keys(conditions).every(key => row[key] == conditions[key])) {
				count++;
				return { ...row, ...updates };
			}
			return row;
		});
		
		return count;
	}

	delete(tableName, conditions) {
		if (!this.tables[tableName]) throw new Error(`Table ${tableName} does not exist`);
		const table = this.tables[tableName];
		
		const originalLength = table.rows.length;
		table.rows = table.rows.filter(row => 
			!Object.keys(conditions).every(key => row[key] == conditions[key])
		);
		
		return originalLength - table.rows.length;
	}

	count(tableName) {
		if (!this.tables[tableName]) throw new Error(`Table ${tableName} does not exist`);
		return this.tables[tableName].rows.length;
	}

	groupBy(tableName, groupColumn, aggregates = {}) {
		if (!this.tables[tableName]) throw new Error(`Table ${tableName} does not exist`);
		const table = this.tables[tableName];
		const groups = {};

		table.rows.forEach(row => {
			const key = row[groupColumn];
			if (!groups[key]) groups[key] = [];
			groups[key].push(row);
		});

		return Object.entries(groups).map(([groupVal, rows]) => ({
			[groupColumn]: groupVal,
			COUNT: rows.length,
			...aggregates
		}));
	}
}

const SAMPLE_QUERIES = {
	"View All Users": "SELECT * FROM users;",
	"Count Users": "SELECT COUNT(*) FROM users;",
	"Users by Department": "SELECT department, COUNT(*) FROM users GROUP BY department;",
	"Insert New User": "INSERT INTO users (name, email, department, salary) VALUES ('John Doe', 'john@example.com', 'Engineering', 75000);",
	"Update Salary": "UPDATE users SET salary = 80000 WHERE name = 'John Doe';",
	"Delete User": "DELETE FROM users WHERE name = 'John Doe';",
	"Engineering Team": "SELECT * FROM users WHERE department = 'Engineering';",
	"Top Earners": "SELECT name, salary FROM users WHERE salary > 75000;",
};

const Sql = () => {
	const { theme } = useTheme();
	const isDark = theme === "dark";
	const [code, setCode] = useState("SELECT * FROM users;");
	const [output, setOutput] = useState("");
	const [db, setDb] = useState(null);
	const [loading, setLoading] = useState(false);
	const [error, setError] = useState("");
	const [executionTime, setExecutionTime] = useState(0);
	const [dbReady, setDbReady] = useState(false);

	// Initialize database with sample data
	useEffect(() => {
		const initDatabase = () => {
			try {
				const newDb = new SimpleSQL();
				
				// Create users table
				newDb.createTable("users", ["id", "name", "email", "department", "salary"]);
				
				// Insert sample data
				const sampleData = [
					{ id: 1, name: "Alice Johnson", email: "alice@example.com", department: "Engineering", salary: 85000 },
					{ id: 2, name: "Bob Smith", email: "bob@example.com", department: "Sales", salary: 65000 },
					{ id: 3, name: "Carol White", email: "carol@example.com", department: "Marketing", salary: 70000 },
					{ id: 4, name: "David Brown", email: "david@example.com", department: "Engineering", salary: 88000 },
					{ id: 5, name: "Eve Davis", email: "eve@example.com", department: "HR", salary: 60000 },
				];
				
				sampleData.forEach(data => {
					newDb.insert("users", data);
					newDb.autoIncrement["users"] = Math.max(newDb.autoIncrement["users"], (data.id || 0) + 1);
				});
				
				setDb(newDb);
				setDbReady(true);
				setOutput("✓ Database initialized with sample data. Ready to execute queries!");
				setError("");
			} catch (err) {
				setError(`Initialization error: ${err.message}`);
				setOutput("");
			}
		};

		initDatabase();
	}, []);

	const parseAndExecuteSQL = (sql) => {
		const trimmed = sql.trim().toUpperCase();
		const originalSql = sql.trim();

		try {
			// SELECT
			if (trimmed.startsWith("SELECT")) {
				const fromMatch = originalSql.match(/FROM\s+(\w+)/i);
				const tableName = fromMatch ? fromMatch[1] : null;
				const whereMatch = originalSql.match(/WHERE\s+(.+?)(?:GROUP|ORDER|;|$)/i);
				const groupMatch = originalSql.match(/GROUP\s+BY\s+(\w+)/i);
				const countMatch = originalSql.match(/COUNT\(\*\)/i);

				if (!tableName) throw new Error("Table name not specified in SELECT");

				let results;

				if (groupMatch) {
					const groupColumn = groupMatch[1];
					results = db.groupBy(tableName, groupColumn);
					return {
						columns: Object.keys(results[0] || {}),
						rows: results,
					};
				}

				const conditions = {};
				if (whereMatch) {
					const whereClause = whereMatch[1];
					const condMatch = whereClause.match(/(\w+)\s*=\s*['"]*([^'"]+)['"]*$/i);
					if (condMatch) {
						conditions[condMatch[1]] = isNaN(condMatch[2]) ? condMatch[2] : Number(condMatch[2]);
					}
				}

				if (countMatch) {
					const count = db.select(tableName, conditions).rows.length;
					return {
						columns: ["COUNT(*)"],
						rows: [[count]],
					};
				}

				results = db.select(tableName, conditions);
				return results;
			}

			// INSERT
			if (trimmed.startsWith("INSERT")) {
				const tableMatch = originalSql.match(/INTO\s+(\w+)/i);
				const columnsMatch = originalSql.match(/\(([^)]+)\)/);
				const valuesMatch = originalSql.match(/VALUES\s*\(([^)]+)\)/i);

				const tableName = tableMatch ? tableMatch[1] : null;
				const columns = columnsMatch ? columnsMatch[1].split(',').map(c => c.trim()) : [];
				const values = valuesMatch ? valuesMatch[1].split(',').map(v => {
					const trimmed = v.trim();
					return trimmed.startsWith("'") || trimmed.startsWith('"') ? trimmed.slice(1, -1) : isNaN(trimmed) ? trimmed : Number(trimmed);
				}) : [];

				const data = {};
				columns.forEach((col, i) => {
					data[col] = values[i];
				});

				db.insert(tableName, data);
				return { columns: ["Message"], rows: [["✓ Row inserted"]] };
			}

			// UPDATE
			if (trimmed.startsWith("UPDATE")) {
				const tableMatch = originalSql.match(/UPDATE\s+(\w+)/i);
				const setMatch = originalSql.match(/SET\s+(\w+)\s*=\s*(\d+)/i);
				const whereMatch = originalSql.match(/WHERE\s+(\w+)\s*=\s*['"]*([^'"]+)['"]*$/i);

				const tableName = tableMatch ? tableMatch[1] : null;
				const updates = {};
				if (setMatch) {
					updates[setMatch[1]] = isNaN(setMatch[2]) ? setMatch[2] : Number(setMatch[2]);
				}
				const conditions = {};
				if (whereMatch) {
					conditions[whereMatch[1]] = isNaN(whereMatch[2]) ? whereMatch[2] : whereMatch[2];
				}

				const count = db.update(tableName, updates, conditions);
				return { columns: ["Message"], rows: [[`✓ ${count} row(s) updated`]] };
			}

			// DELETE
			if (trimmed.startsWith("DELETE")) {
				const tableMatch = originalSql.match(/FROM\s+(\w+)/i);
				const whereMatch = originalSql.match(/WHERE\s+(\w+)\s*=\s*['"]*([^'"]+)['"]*$/i);

				const tableName = tableMatch ? tableMatch[1] : null;
				const conditions = {};
				if (whereMatch) {
					conditions[whereMatch[1]] = isNaN(whereMatch[2]) ? whereMatch[2] : whereMatch[2];
				}

				const count = db.delete(tableName, conditions);
				return { columns: ["Message"], rows: [[`✓ ${count} row(s) deleted`]] };
			}

			// CREATE TABLE
			if (trimmed.startsWith("CREATE")) {
				const tableMatch = originalSql.match(/CREATE\s+TABLE\s+IF\s+NOT\s+EXISTS\s+(\w+)/i) || originalSql.match(/CREATE\s+TABLE\s+(\w+)/i);
				const columnsMatch = originalSql.match(/\(([^)]+)\)/);

				const tableName = tableMatch ? tableMatch[1] : null;
				const columns = columnsMatch ? columnsMatch[1].split(',').map(c => c.trim().split(/\s+/)[0]) : [];

				db.createTable(tableName, columns);
				return { columns: ["Message"], rows: [["✓ Table created"]] };
			}

			// DROP TABLE
			if (trimmed.startsWith("DROP")) {
				const tableMatch = originalSql.match(/DROP\s+TABLE\s+IF\s+EXISTS\s+(\w+)/i) || originalSql.match(/DROP\s+TABLE\s+(\w+)/i);
				const tableName = tableMatch ? tableMatch[1] : null;

				const dropped = db.dropTable(tableName);
				return { columns: ["Message"], rows: [[dropped ? "✓ Table dropped" : "✗ Table not found"]] };
			}

			throw new Error("Unsupported SQL command");
		} catch (err) {
			throw new Error(err.message);
		}
	};

	const handleRunCode = () => {
		if (!db || !dbReady) {
			setOutput("❌ Database not ready...");
			setError("Database initialization in progress");
			return;
		}

		if (!code.trim()) {
			setOutput("⚠️ Please enter a SQL query");
			return;
		}

		try {
			setError("");
			const startTime = performance.now();

			const statements = code.split(";").filter((stmt) => stmt.trim());
			let allOutputs = [];

			for (let i = 0; i < statements.length; i++) {
				const statement = statements[i].trim();
				if (!statement) continue;

				try {
					const result = parseAndExecuteSQL(statement);
					const columns = result.columns;
					const rows = result.rows;
					
					allOutputs.push({
						queryNum: i + 1,
						columns,
						rows,
						isSelect: statement.trim().toUpperCase().startsWith("SELECT")
					});
				} catch (queryErr) {
					allOutputs.push({
						queryNum: i + 1,
						error: queryErr.message
					});
				}
			}

			const endTime = performance.now();
			setExecutionTime((endTime - startTime).toFixed(2));
			setOutput(JSON.stringify(allOutputs));
		} catch (err) {
			setError(`Execution error: ${err.message}`);
			setOutput(`❌ ${err.message}`);
		}
	};

	const handleLoadSample = (query) => {
		setCode(query);
	};

	const handleClear = () => {
		setCode("");
		setOutput("");
		setError("");
		setExecutionTime(0);
	};

	const handleReset = () => {
		setCode("");
		setOutput("");
		setError("");
		setExecutionTime(0);
		if (db && dbReady) {
			try {
				db.dropTable("users");
				db.createTable("users", ["id", "name", "email", "department", "salary"]);
				
				const sampleData = [
					{ id: 1, name: "Alice Johnson", email: "alice@example.com", department: "Engineering", salary: 85000 },
					{ id: 2, name: "Bob Smith", email: "bob@example.com", department: "Sales", salary: 65000 },
					{ id: 3, name: "Carol White", email: "carol@example.com", department: "Marketing", salary: 70000 },
					{ id: 4, name: "David Brown", email: "david@example.com", department: "Engineering", salary: 88000 },
					{ id: 5, name: "Eve Davis", email: "eve@example.com", department: "HR", salary: 60000 },
				];
				
				sampleData.forEach(data => {
					db.insert("users", data);
					db.autoIncrement["users"] = Math.max(db.autoIncrement["users"], (data.id || 0) + 1);
				});
				
				setOutput("✓ Database reset with sample data");
			} catch (err) {
				setError(`Reset error: ${err.message}`);
			}
		}
	};

	return (
		<div
			className={`container-fluid mt-4 ${isDark ? "bg-dark text-light" : "bg-light text-dark"}`}
			style={{ minHeight: "100vh", padding: "24px" }}
		>
			{/* Header */}
			<div className="mb-4">
				<h1 className="mb-2" style={{ fontSize: "2.5rem", fontWeight: "700" }}>SQL Code Editor</h1>
				<p className={isDark ? "text-white-50" : "text-muted"} style={{ fontSize: "1rem", marginBottom: "16px" }}>
					Write and execute SQL queries with sample data. No external dependencies required.
				</p>
				{error && (
					<div className="alert alert-warning mb-3 d-inline-block" role="alert" style={{ fontSize: "14px" }}>
						⚠️ {error}
					</div>
				)}
				{dbReady && (
					<div className="alert alert-success mb-3 d-inline-block" role="alert" style={{ fontSize: "14px", marginLeft: "12px" }}>
						✓ Database Ready
					</div>
				)}
			</div>

			{/* Main Grid Layout */}
			<div
				style={{
					display: "grid",
					gridTemplateColumns: "1fr 1fr",
					gap: "24px",
					height: "calc(100vh - 200px)",
					minHeight: "700px",
				}}
			>
				{/* Code Editor Section - Left */}
				<div
					style={{
						display: "flex",
						flexDirection: "column",
						gap: "16px",
					}}
				>
					{/* Code Editor Card */}
					<div
						className={`card ${isDark ? "bg-secondary text-light border-secondary" : "bg-light"}`}
						style={{
							borderRadius: "12px",
							border: isDark ? "1px solid rgba(255,255,255,0.12)" : "1px solid rgba(0,0,0,0.12)",
							display: "flex",
							flexDirection: "column",
							height: "100%",
							boxShadow: isDark ? "0 4px 12px rgba(0,0,0,0.3)" : "0 2px 8px rgba(0,0,0,0.08)",
							overflow: "hidden",
						}}
					>
						<div 
							className={`card-header ${isDark ? "bg-dark" : "bg-light"}`}
							style={{
								padding: "16px 20px",
								borderBottom: isDark ? "1px solid rgba(255,255,255,0.08)" : "1px solid rgba(0,0,0,0.08)",
								backgroundColor: isDark ? "#1a1a1a" : "#f8f9fa",
							}}
						>
							<h5 className="mb-0" style={{ fontSize: "1.1rem", fontWeight: "600" }}>
								<span style={{ marginRight: "8px" }}>📝</span>SQL Query
							</h5>
						</div>
						<div 
							className="card-body" 
							style={{ 
								flex: 1, 
								display: "flex", 
								flexDirection: "column", 
								padding: "16px",
								overflow: "hidden",
							}}
						>
							<textarea
								className={`form-control ${isDark ? "bg-dark text-light border-secondary" : "bg-white text-dark"}`}
								value={code}
								onChange={(e) => setCode(e.target.value)}
								placeholder="-- Enter your SQL query here..."
								disabled={!dbReady}
								style={{
									fontFamily: "'Courier New', 'Monaco', monospace",
									fontSize: "13px",
									flex: 1,
									marginBottom: "12px",
									resize: "none",
									borderRadius: "6px",
									padding: "12px",
									lineHeight: "1.6",
									backgroundColor: isDark ? "#0d1117" : "#f6f8fa",
									borderColor: isDark ? "rgba(255,255,255,0.08)" : "rgba(0,0,0,0.08)",
									color: isDark ? "#e0e0e0" : "#24292e",
								}}
							/>

							{/* Action Buttons */}
							<div className="d-flex gap-2 flex-wrap" style={{ justifyContent: "space-between" }}>
								<button
									className="btn btn-success"
									onClick={handleRunCode}
									disabled={!dbReady}
									style={{ 
										flex: "1 1 auto",
										fontWeight: "600",
										padding: "10px 16px",
										fontSize: "14px",
										borderRadius: "6px",
										border: "none",
										transition: "all 0.2s ease",
									}}
									onMouseEnter={(e) => !dbReady && (e.target.style.opacity = "0.7")}
									onMouseLeave={(e) => !dbReady && (e.target.style.opacity = "1")}
								>
									▶️ Run
								</button>
								<button
									className="btn btn-info"
									onClick={handleClear}
									style={{ 
										flex: "1 1 auto",
										fontWeight: "600",
										padding: "10px 16px",
										fontSize: "14px",
										borderRadius: "6px",
										border: "none",
										transition: "all 0.2s ease",
									}}
									onMouseEnter={(e) => (e.target.style.opacity = "0.85")}
									onMouseLeave={(e) => (e.target.style.opacity = "1")}
								>
									🧹 Clear
								</button>
								<button
									className="btn btn-warning"
									onClick={handleReset}
									disabled={!dbReady}
									style={{ 
										flex: "1 1 auto",
										fontWeight: "600",
										padding: "10px 16px",
										fontSize: "14px",
										borderRadius: "6px",
										border: "none",
										transition: "all 0.2s ease",
									}}
									onMouseEnter={(e) => !dbReady && (e.target.style.opacity = "0.7")}
									onMouseLeave={(e) => !dbReady && (e.target.style.opacity = "1")}
								>
									🔄 Reset
								</button>
							</div>
						</div>
					</div>

					{/* Sample Queries */}
					<div
						style={{
							padding: "16px 20px",
							backgroundColor: isDark ? "#1a1a1a" : "#f8f9fa",
							borderRadius: "12px",
							border: isDark ? "1px solid rgba(255,255,255,0.08)" : "1px solid rgba(0,0,0,0.08)",
							boxShadow: isDark ? "0 2px 8px rgba(0,0,0,0.2)" : "0 1px 4px rgba(0,0,0,0.05)",
						}}
					>
						<h6 className="mb-3" style={{ fontSize: "0.95rem", fontWeight: "600" }}>
							📋 Sample Queries:
						</h6>
						<div
							style={{
								display: "grid",
								gridTemplateColumns: "repeat(2, 1fr)",
								gap: "8px",
								maxHeight: "120px",
								overflowY: "auto",
							}}
						>
							{Object.entries(SAMPLE_QUERIES).map(([label, query]) => (
								<button
									key={label}
									className="btn btn-sm btn-outline-primary"
									onClick={() => handleLoadSample(query)}
									disabled={!dbReady}
									title={query}
									style={{ 
										fontSize: "12px", 
										textAlign: "left",
										padding: "6px 10px",
										fontWeight: "500",
										borderRadius: "6px",
									}}
								>
									{label}
								</button>
							))}
						</div>
					</div>
				</div>

				{/* Output Section - Right */}
				<div
					style={{
						display: "flex",
						flexDirection: "column",
					}}
				>
					<div
						className={`card ${isDark ? "bg-secondary text-light border-secondary" : "bg-light"}`}
						style={{
							borderRadius: "12px",
							border: isDark ? "1px solid rgba(255,255,255,0.12)" : "1px solid rgba(0,0,0,0.12)",
							display: "flex",
							flexDirection: "column",
							height: "100%",
							boxShadow: isDark ? "0 4px 12px rgba(0,0,0,0.3)" : "0 2px 8px rgba(0,0,0,0.08)",
							overflow: "hidden",
						}}
					>
						<div 
							className={`card-header ${isDark ? "bg-dark" : "bg-light"}`}
							style={{
								padding: "16px 20px",
								borderBottom: isDark ? "1px solid rgba(255,255,255,0.08)" : "1px solid rgba(0,0,0,0.08)",
								backgroundColor: isDark ? "#1a1a1a" : "#f8f9fa",
								display: "flex",
								justifyContent: "space-between",
								alignItems: "center",
							}}
						>
							<h5 className="mb-0" style={{ fontSize: "1.1rem", fontWeight: "600" }}>
								<span style={{ marginRight: "8px" }}>📊</span>Results
							</h5>
							{executionTime > 0 && (
								<small 
									className={isDark ? "text-white-50" : "text-muted"}
									style={{ fontSize: "12px", fontWeight: "500" }}
								>
									⏱️ {executionTime}ms
								</small>
							)}
						</div>
						<div
							className="card-body"
							style={{
								flex: 1,
								overflow: "auto",
								padding: "16px",
								backgroundColor: isDark ? "#0d1117" : "#f6f8fa",
								borderRadius: "0 0 12px 12px",
							}}
						>
							{output ? (
								(() => {
									try {
										const results = JSON.parse(output);
										return (
											<div>
												{results.map((result, idx) => (
													<div key={idx} style={{ marginBottom: "20px" }}>
														<div style={{ 
															fontSize: "12px", 
															fontWeight: "600", 
															marginBottom: "8px",
															color: isDark ? "#a0a0a0" : "#666"
														}}>
															Query {result.queryNum}
														</div>
														
														{result.error ? (
															<div style={{ color: "#ff6b6b", fontSize: "13px", fontFamily: "monospace" }}>
																❌ {result.error}
															</div>
														) : result.isSelect ? (
															<div style={{ overflowX: "auto" }}>
																<table style={{
																	width: "100%",
																	borderCollapse: "collapse",
																	fontSize: "12px",
																	border: isDark ? "1px solid rgba(255,255,255,0.1)" : "1px solid rgba(0,0,0,0.1)",
																	backgroundColor: isDark ? "#161b22" : "#ffffff"
																}}>
																	<thead>
																		<tr style={{ 
																			backgroundColor: isDark ? "#0d47a1" : "#e3f2fd",
																			borderBottom: isDark ? "2px solid rgba(255,255,255,0.1)" : "2px solid rgba(0,0,0,0.1)"
																		}}>
																			{result.columns.map((col, i) => (
																				<th key={i} style={{
																					padding: "8px 12px",
																					textAlign: "left",
																					fontWeight: "600",
																					color: isDark ? "#e0e0e0" : "#1565c0"
																				}}>
																					{col}
																				</th>
																			))}
																		</tr>
																	</thead>
																	<tbody>
																		{result.rows.map((row, rowIdx) => (
																			<tr key={rowIdx} style={{
																				borderBottom: isDark ? "1px solid rgba(255,255,255,0.08)" : "1px solid rgba(0,0,0,0.08)",
																				backgroundColor: rowIdx % 2 === 0 ? (isDark ? "transparent" : "#fafafa") : (isDark ? "#0d1117" : "#ffffff")
																			}}>
																				{result.columns.map((col, colIdx) => {
																					const value = Array.isArray(row) ? row[colIdx] : row[col];
																					return (
																						<td key={colIdx} style={{
																							padding: "8px 12px",
																							color: isDark ? "#e0e0e0" : "#24292e"
																						}}>
																							{value === null || value === undefined ? "NULL" : String(value)}
																						</td>
																					);
																				})}
																			</tr>
																		))}
																	</tbody>
																</table>
																<div style={{
																	marginTop: "8px",
																	fontSize: "12px",
																	color: isDark ? "#a0a0a0" : "#666",
																	fontWeight: "500"
																}}>
																	({result.rows.length} rows)
																</div>
															</div>
														) : (
															<div style={{ 
																color: isDark ? "#4caf50" : "#2e7d32",
																fontSize: "13px",
																fontWeight: "500",
																fontFamily: "monospace"
															}}>
																{Array.isArray(result.rows) && result.rows.length > 0 
																	? (Array.isArray(result.rows[0]) 
																		? result.rows[0][0]
																		: Object.values(result.rows[0])[0])
																	: "✓ Executed successfully"
																}
															</div>
														)}
													</div>
												))}
											</div>
										);
									} catch (e) {
										return (
											<pre style={{
												margin: 0,
												fontFamily: "'Courier New', 'Monaco', monospace",
												fontSize: "12px",
												lineHeight: "1.6",
												whiteSpace: "pre-wrap",
												wordWrap: "break-word",
												color: isDark ? "#e0e0e0" : "#24292e",
											}}>
												{output}
											</pre>
										);
									}
								})()
							) : (
								<div style={{ color: isDark ? "#a0a0a0" : "#666", fontSize: "13px" }}>
									✓ Ready. Click 'Run' to execute...
								</div>
							)}
						</div>
					</div>
				</div>
			</div>
		</div>
	);
};

export default Sql;
